quests[66457] = { id = 66457, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ending the Blue Period", description = "The Embertooth all follow an oversized brute that I've taken to calling Bluescale. He has always been the aggressive sort, but until now he's always kept his pack of scavengers away from the main roads. Sure, they were territorial, but hostile? Not until now.\n\nBluescale has to be responsible for this sudden escalation. Find him and take him down.", progress = "Be careful, {class}. Bluescale is tougher than your average Tarasek scavenger.", completion = "With Bluescale taken care of, I doubt we will have to deal with any organized tarasek encroachment any time soon.\n\nNow all that's left is to deal with the poison.", objectives = "Slay Bluescale.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66458] = { id = 66458, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Legacy of Tyr: Secrets of the Past", description = "To stop Raszageth from freeing the other Incarnates, the power of the Aspects must be restored.\n\nInconveniently, the Titans are rather preoccupied and Keeper Tyr is long dead.\n\nQueen Alexstrasza has suggested a plan. In the depths of the Badlands lies a Titan facility called Uldaman. Apparently allies of Tyr may have hidden a disc of his memories there.\n \nWord is that the place has been overrun by troggs. Gather your allies, head to Uldaman, and seize the disc in the name of the Dragon Queen!", progress = "Did you retrieve the disc?", completion = "Infinite dragons? Their kind always has some kind of plan.\n\nI will inform the Dragon Queen that she will have to find some other way to restore the power of the Aspects.", objectives = "Enter Uldaman: Legacy of Tyr in the Badlands and recover the disc.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66459] = { id = 66459, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Field of Ferocity: Terror of the Swamp!", description = "Welcome one and all to the Fields of Ferocity!\n \nWhile this sparring field is used for traditional events, the centaurs have graciously allowed me to set up shop off-season. They say it tests their strength and brings them honor.\n \nYou want to take home the title of champion? Well then, let me know when you're ready and you can take on the introductory competition.", progress = "Speak with Gurgthock to start the round, then defeat the first competitor of the Field of Ferocity.", completion = "You've done well, for the first ladder. But we're just warming up. Speak with Gurgthock again when you're ready to move on to the second round.", objectives = "Defeat Maneet.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66460] = { id = 66460, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Field of Ferocity: Lord of Decay!", description = "I tried to get one of those nasty gnolls for this gauntlet. Unfortunately, none of my associates know how to speak with them.\n \nWe did manage to catch one of their freaky creations though. That should serve as a good opponent! Let me know when you want to start the second round!", progress = "Well, what are you waiting for?  Speak with Gurgthock to start the round, then defeat the second competitor of the Field of Ferocity.", completion = "I'm glad you dealt with that as quickly as you did. The stench was starting to reach the podium here.", objectives = "Defeat Nightrot.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66461] = { id = 66461, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Field of Ferocity: Foe from the Volcano!", description = "One of the first volunteers for this competition hails from the Waking Shores. A big djaradin fellow, not quite as angry as his kin.\n \nHe just seems to enjoy the sport of fighting. Hey, that works for me.", progress = "Ceega has a famous entrance. You need to speak with Gurgthock to start the round, then defeat the third competitor of the Field of Ferocity.", completion = "What a show! I could feel sparks flying from here!", objectives = "Defeat Ceeqa the Peacetaker.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66462] = { id = 66462, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Field of Ferocity: Lost in the Dream!", description = "You know, for it being the Dragon Isles, I haven't seen too many dragons. We did get a duo of dragonkin that requested to be signed up for this competition together though.\n \nThey seem plenty eager to prove themselves though, so good luck!", progress = "You need to speak with Gurgthock to start the round, then defeat the fourth competitors of the Field of Ferocity.", completion = "... Wuzzat? Is the fight over? I think I fell asleep in the middle of it for some reason.\n\nI'm guessing you won if you're standing in front of me?", objectives = "Defeat Sherath and Taresh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66463] = { id = 66463, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Field of Ferocity: Elemental Revenge Round!", description = "We're changing the roster at the last minute. Some Primalist bigwig wants to join in on the competition to face you. And I'm not saying no to an angry elemental dragon.\n \nI'm sure you'll be fine. If not, then... well, you signed the waiver, right?", progress = "You need to speak with Gurgthock to start the round, then defeat the fifth competitor of the Field of Ferocity.", completion = "I now understand the rumors I have heard about you and your crew. You have gotten further than I would have ever expected.", objectives = "Defeat the Primalist champion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66464] = { id = 66464, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Field of Ferocity: Master of the Hunt!", description = "This is it. You and your pals have hit the big time. A match against the champ, Huntmaster Amaa herself. Don't pat yourself on the back just yet. She's ruthless. It was nice knowing you.\n \nAfter she kills you, can I have your stuff?", progress = "You need to speak with Gurgthock to start the round, then defeat the final competitor of the Field of Ferocity. Good luck.", completion = "You are quite the impressive and fearsome combatant. The centaurs are in awe of you. Gurgthock is fuming for not betting his farm on you instead of Amaa. You win the grand prize.", objectives = "Defeat Huntmaster Amaa.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66465] = { id = 66465, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cache and Release", description = "Even with their leader gone, the Tarasek are unlikely to stop using their poison-tipped spears simply because we ask them nicely. I cannot risk even one of these weapons being used on an unsuspecting traveler.\n\nThey will all need to be destroyed. If you did not see any in the caches by the pools, then the Embertooth are likely keeping their spears closer to the source. \n\nNo one else will get hurt because of my carelessness. Enter the cave and destroy any weapon caches that you find.", completion = "The Passage will be a far safer place without those poisoned spears to worry about.\n\nYou have kept a lot of people safe with your deeds this day, {name}. The Waywatchers - and I - owe you a great debt.", objectives = "Destroy 8 Poisoned Spear Stashes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66467] = { id = 66467, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Art Imitates Life", description = "The last time I was in this cave, I sketched a massive flower that dripped a vile, viscous sap. It's one of my best drawings, I couldn't forget it if I tried.\n\nThat sap is what's stuck to these tarasek spears, I'm sure of it. They must have started harvesting it to envenom their weapons.\n\nThe plant is beautiful; it will be a shame to kill it. Still, we can't let the tarasek keep harvesting it. {name}, please cull the plant and put a stop to this whole mess.", completion = "Thank you, {name}. The Embertooth's venom harvesting days should be behind them now that they have been deprived of their source.\n\nI realize now that I don't have to be a Waywatcher to make a difference in the world. I am going to resign my post and commit myself to my art. Hopefully some day I will be able to depict the most beautiful vistas in the Dragon Isles, for all the world to see.\n\nI just hope my sister understands.", objectives = "Slay the Greater Venomsprout.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66468] = { id = 66468, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What Once Was Ours", description = "<Thadezus scoffs at your approach.>\n\nAre you a mortal of action, or are you going to get out of our way, {class}?\n\nI have lost many good soldiers to those Primalists up ahead.\n\nWe have an idea of what they are planning, but we must first rout the enemy and rescue those serving under me.", progress = "Have you stopped the Primalists, or do I need to do this myself?", completion = "<Sharnax stares down at you.>\n\nHmm... It appears you are someone with more skill than the commander had originally assumed.\n\nThere is more to be done before the day is over.", objectives = "Defeat the Primalists occupying the Gelikyr Overlook.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66470] = { id = 66470, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Forward Push", description = "<Sharnax scratches her chin.>\n\nThe commander was right. The Primalists are calling reinforcements from the elemental planes.\n\n<Sharnax smirks.>\n\nIt would be a shame if something happened to their gateways, {class}.", progress = "We need to close those gateways.", completion = "Looks like you made it in one piece.", objectives = "Obtain Misttouched, Earthen, and Iceforged gateway stones, and close the 3 elemental gateways.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66471] = { id = 66471, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prime Planning", description = "The commander ordered me to establish a forward base and dispatch any resistance. It wasn't until I did all the dispatching that I realized something.\n\n<Sharnax lets out a long sigh.>\n\nThe Primalists were talking about Tyrhold.\n\nUnless you are exceptionally skilled at interrogation, I need you to discover their plans.", progress = "Do you have something we can show the commander?", completion = "This is just what we needed.", objectives = "Collect 7 Primalist Orders from the nearby Primalists in the upper terrace of Gelikyr Overlook.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66472] = { id = 66472, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Primal List", description = "The gateways closed, the elementals slain, and the Primalists stopped... for now.\n\n<Sharnax laughs.>\n\nIs there anything we cannot do, {class}? I guess only time will tell.\n\nTake the plans back to the commander. I am certain he will be glad to see we have been successful.", progress = "<Thadezus stares at you.>\n\nWhat do you want, {class}?", completion = "<Thadezus pauses for an uncomfortable amount of time.>\n\nAllis and I had bets on if you would be successful, {class}\n\n I am glad that you were.", objectives = "Deliver the Bundle of Primalist Orders to Commander Thadezus on the bridge at the Gelikyr Overlook.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66473] = { id = 66473, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Land Awakens", description = "The fiends in this cave were too much for me.\n\n<Sharnax lets out a labored cough.>\n\nI have seen what you can do.\n\nI need you to slay these elementals before they reach their full potential. We cannot allow the Primalists to take control of Tyrhold!", progress = "<Sharnax coughs.>\n\nIs it done?", completion = "Thank you for everything you have done for us, {class}.", objectives = "Defeat the Primordial Wrath and Primordial Hail in the Gelikyr Overlook.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66482] = { id = 66482, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scout for Trophies: Terramaw" }
quests[66484] = { id = 66484, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Know Your Enemy: Proto-Dragons", description = "The area is crawling with those powerful beasts! Conveniently. the Surveying Scope has allowed you to spot a few weak spot in their tough scale. You can also devise a few tricks to avoid their sharp claws and fangs.", objectives = "Hunt down a few Proto-Dragons around the Apex Canopy.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66488] = { id = 66488, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "WANTED: Frigellus", description = "<The page's script glows with a soft blue light.>\n\nPreviously a cherished plaything of Malygos, the elemental Frigellus suffered from his master's neglect. \n\nWhile this once-happy settlement crumbled apace, the churlish and playful creature grew warped and twisted by the evils that plague this land.\n\nPlease see that it is safely neutralized.\n\nBring word of your success to Custodian Cynegos.", progress = "Return to Custodian Cynegos in Camp Antonidas.", completion = "Let us hope there aren't any more surprises trapped in that glacier.", objectives = "Kill Frigellus near Camp Antonidas.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66489] = { id = 66489, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Setting the Defense", description = "Custodian Cynegos and I were just discussing the impact the Primalist attack has had on the plans to assault the Cobalt Assembly, and I had an idea. \n\n<Celeste withdraws a wand from the folds of her robes.>\n\nTake my wand and empower their weapons!\n\nA little bit of fire should do the trick...", progress = "Have they been sufficiently enchanted?", completion = "Fantastic job! \n\nAfter repelling their attack on the camp, it's imperative that we keep the Primalists on the back foot. \n\nNow please give me my wand back.", objectives = "Empower Azure Defenders in Camp Antonidas.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66493] = { id = 66493, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Send It!", description = "<You hear muffled muttering coming from the other end of the portal.>\n\nHey! Hey you! \n\nI have some mail for our apprentices in the field: care packages, gifts, things they've ordered via magical courier... \n\nStandard fare, really.\n\nMind doing me a favor and handing them out?", progress = "How's your arm? \n\nDon't forget to stretch, or you might hurt yourself.", completion = "Well done! Don't worry... it's the courier's fault if a parcel wasn't marked \"fragile.\"", objectives = "Throw packages to Kirin Tor Apprentices in Camp Antonidas.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66500] = { id = 66500, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ways of Seeing", description = "We're not doing anything! We're not doing anything!\n\nHang on a minute...\n\nYou look like a pretty important {race}... Want in on a secret?\n\nTurns out there's magical art in these ruins. And we can see it!\n\n<Scrumpy proudly sticks out his chest.>\n\nI can show you how to see 'em too! Just... don't tell Noriko yet.", progress = "Noriko told us to stay out of trouble. Not sure how to do that to be honest.", completion = "Malygos and Sindragosa, huh? Never heard of 'em. Sounds like they were pretty in love though.\n\nI wonder who put these here?", objectives = "Uncover ancient images in Camp Antonidas.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66503] = { id = 66503, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "For The Love of Others", description = "Ah, I see my apprentices have roped you into their little games. \n\n<Noriko chuckles.>\n\nIt appears they--and you--have stumbled onto something. The purpose behind these ruins is slowly revealing itself to us, and there's more than faded images and song...\n\nSomething calls out from atop this tower.\n\nI see the intrigue in your eyes. Go. You have my permission. \n\nSee what you can see.", progress = "Remembrance is a gift--and a burden.", completion = "To watch your world crumble into ruin and think it lost forever...\n\nI cannot imagine.\n\nWe must remember.", objectives = "Investigate the top of the Ruined Tower in Camp Antonidas.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66504] = { id = 66504, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Shard of Crystalized Mana", description = "<The small blue crystal vibrates lightly when touched, then produces a low tune that sounds like a distant song. You can hear the words echoing like a soft melody in your head.>\n\nLathos may find it interesting.", objectives = "Take the crystal to Lathos.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66507] = { id = 66507, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Winter Veil Gift", objectives = "A small tag on this present reads:\n\nHappy holidays, {name}!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66508] = { id = 66508, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Gently Shaken Gift", objectives = "This present looks like it has been shaken a few times. The tag on it reads:\n\nTo a very special {race} {class}.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66509] = { id = 66509, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paranoid 1", description = "Agura sent me out here to pick FLOWERS for my ANXIETY but there are CREATURES and I'm terrified." }
quests[66511] = { id = 66511, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Renowned with the Iskaara Tuskarr", description = "You continue to show us that you are an integral member of our community. \n\nTo honor that bond seek me out in Iskaara as I have prepared a pack of supplies to aid you.", completion = "Again, we can only thank you so much and these supplies do not do that thank you justice, but please know your aid means a great deal to us!", objectives = "Speak with Murik in Iskaara.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66513] = { id = 66513, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ground Leave", description = "Perhaps we should get an idea of this city, if it is to be our new home. A scouting mission, if you will.\n\nGo, see what this place has to offer. I will follow Wrathion and attempt to help in any way I can.\n\nTry not to upset the locals any more than you must, though. I doubt many of them are used to seeing dragons walk among them.\n\nMeet up with us once you've gotten the lay of the land.", completion = "The Alliance has granted us asylum here in Stormwind.\n\nIt sounds like quite an interesting place.", objectives = "Explore Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66516] = { id = 66516, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mundane Gems, I Think Not!", description = "It's such a waste. The djaradin of this land use powerful gems as mundane decorations. Mere jewelry! Gems have so many uses: telescopes, mirrors, focusing pointers, not to mention the myriad magical properties they possess.\n\nWe must rectify this situation, explorer. Relieve the djaradin of their gems, and bring them back to me. I'll make sure they're put to better use! Be careful though--the djaradin are fierce warriors.", progress = "Were you able to get the gems?", completion = "There's so much potential in these gems, even Lugrah wouldn't know what to do with them all!\n\nLugrah is the jewelcrafting representative to the Artisan Consortium. Let me share some of the notes she sent me before I left. They're sure to help you with your jewelcrafting studies here in the Dragon Isles.", objectives = "Gather 25 'Mundane' Gems from the djaradin of the Dragon Isles for Gnoklin Quirkcoil of the Dragonscale Expedition.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66517] = { id = 66517, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A New Source of Weapons", description = "These Sundered Flame pose a great threat to our borders. Their weapons are concerning. Gather what you can of their weapons--we can study them for any weaknesses, and even use them for our own defenses.\n\nI have faith in you, outsider. If you perform this task for us, I will teach you some of our own blacksmithing arts.", progress = "What were you able to secure?", completion = "Thank you, outsider. This should help greatly.\n\nAs promised, here is a scroll I had our blacksmiths prepare for you. May the knowledge grant you swift learning.", objectives = "Gather 25 Intact Dracthyr Weapons from the Sundered Flame of the Dragon Isles for Dhurrel of the Maruuk Centaurs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66523] = { id = 66523, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tending the Forge", description = "If you're looking for an instructor, I'm sorry to say I... Ah, you're not an apprentice! My apologies. Allow me to introduce myself. \n\nI am Custodian Vernagos, one of the caretakers of these ruins. More specifically, the task of restoring this workspace to its former glory has fallen upon my very tired shoulders. \n\nWould you be able to lend a hand? All the reagents I need are nearby: ice elemental cores, embercones, hornswog leather...\n\nFairly standard, easily gathered stuff. What say you?", progress = "Fresh air and magical relics. What more could one ask for? Ha!", completion = "Thank you, {name}. The embercones will burn hot. The elemental cores will temper the heat. And this leather... is fairly disgusting. But the bellows they produce will more than suffice!\n\nNow all I need is time.", objectives = "Gather reagents for the forge by collecting hornswog hides, dormant embercones, and calving cores around Camp Antonidas.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66524] = { id = 66524, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Amateur Protography", description = "So, you want to be a seasoned cataloger like me? You've come to the right place! \n\nThe Wild Preserve is teeming with knowledge waiting to be found and filed! And how do I do that you ask? Why, with my handy Catalog-izer 3000 Dragon Isles edition--now with improved motion capture!\n\nTo gain experience, photograph a proto-dragon egg, a whelp learning to fly, and a hunting proto-drake. Meet me at the ancient, proto-dragon skeleton west of here, and I'll assess your photos.", completion = "These are wonderful! Just wonderful! Say, have you done this before?", objectives = "Take pictures of proto-dragons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66525] = { id = 66525, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Competitive Protography", description = "Well, now that you've cut your teeth on some starter shots, how about we move onto something a little spicier?\n\nI spotted a gorgeous proto-drake flying around the area behind us. Beautiful horns, scales crackling with electricity... Probably the work of the Primalists, no doubt, but art is art!\n\nSee if you can get a picture of the proto-drake and some of its eggs. You might have to climb up a bit to get a good shot!", progress = "If you get in a fight with the Primalists, make sure you keep that camera pristine! It's my only prototype!", completion = "Oh, look at that! The colors came through beautifully. Looks like you're a pretty good cataloger already!", objectives = "Photograph an Infused Proto-Dragon Egg and an Infused Proto-Drake.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66526] = { id = 66526, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Preserving the Wilds", description = "The Wild Preserve is one of the few areas where proto-dragons thrive. But the Primalists are disrupting their nesting grounds by sending sorties to capture and experiment on proto-whelps and proto-drakes.\n\nShow them no mercy. Locate these Primalist poachers, wipe them out, and free their captives. The proto-dragon species depends on it.", progress = "If we want these creatures to survive, we must protect them.", completion = "Good. The Primalists remain a threat, but these dragons enjoy their freedom once again.", objectives = "Free 5 Captured Proto-Whelps or Captured Proto-Drakes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66527] = { id = 66527, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Professional Protography", description = "I haven't trained a photographer as good as you... that's still alive, that is. It's a dangerous profession.\n\nSpeaking of dangerous, our final target is a large proto-dragon we believe may be one of the next apex predators in this preserve. Let's get up close and personal and take a picture!", progress = "Don't worry, {name}. You're much more competent than the last person I sent up there.", completion = "So totally unrelated, but you didn't see another camera up there, did you?\n\nYou know what? Forget I said anything.", objectives = "Use the Vertical Enhancement Apparatus and photograph the Slumbering Proto-Dragon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66528] = { id = 66528, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "King Without a Crown", description = "This ancient proto-dragon must have been a glorious creature when it was alive--perhaps the largest the Wild Preserve has ever seen.\n\nBut it wasn't enough. Observe the skeleton more closely, so we may learn the story of its final moments.", progress = "An incredible specimen--and a reminder of our origins.", completion = "So, a fight to the death with something just as strong? I wonder if it was protecting the preserve from invaders?\n\nThank you, {name}. It's good to remember the sacrifices of those that have come before us.", objectives = "Investigate the Proto-Dragon Skeleton.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66529] = { id = 66529, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Thousand Words", description = "With all that we've learned here, I can't imagine moving on without a memento. \n\nWould you be kind enough to take my picture next to the proto-dragon fossils?", progress = "It should only take a moment.", completion = "Someday, I hope to fight for my people with the same bravery as this proto-dragon in its final moments.\n\nThanks again, {name}.", objectives = "Photograph Dervishian near the Proto-Dragon Skeleton.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66534] = { id = 66534, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ground Leave", description = "It seems like our arrival was noticed after all. Maybe there's hope for these people yet.\n\nI'll follow up with Ebyssian and the Horde leadership and try to smooth this out. You're on recon.\n\nSee what this place has to offer. We may be here for a while, after all.\n\nCome find us once you're finished. Hopefully we'll have all the boring bits sorted out by then.", completion = "But how was the food?", objectives = "Explore Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66546] = { id = 66546, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Retrieve the Discs", description = "The discs in here represent the sum of this facility's knowledge. We need to retrieve them!\n\nI'll bring the barrier down with this console. It'll be on ye to retrieve the discs.", progress = "Can ye imagine the knowledge that these discs hold?", completion = "I knew we could count on ye!", objectives = "Retrieve the three discs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66547] = { id = 66547, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It Belongs in a Museum... Eventually", description = "Waves of titan security, escaped proto-dragons, keys that turn you into constructs... I'll just say it.\n\nI've never had so much fun in my LIFE!\n\nAlthough Naleidea will probably say this is where the real fun begins. We're sitting on a trove of confidential titan data, thanks to the effort ye put in!\n \nWhen ye can, come meet us at camp and we'll compare notes.", progress = "Thanks again for a once-in-a-lifetime experience!", completion = "Our leads have dried up for now... at least until we can parse more information from these discs.\n\nUntil then, stay observant and follow the clues. You never know where the next adventure will come from!", objectives = "Meet Toddy back at the Dragonscale Expedition camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66549] = { id = 66549, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waking Shores Rally", description = "Fly through the checkpoint rings marking the course." }
quests[66551] = { id = 66551, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Terrible Three", objectives = "Defeat Haniko in a Pet Battle", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66553] = { id = 66553, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hollow Up", description = "The Winterpelt are a special case among the furbolgs. \n\nI'd categorize 'em as a wee bit \"isolationist.\" They are ghosts in the hollow, their pelts blendin' in with tha snow. \n\nUsedta keep to themselves, but now they're outright aggressive. They attacked our camp with nae provocation!\n\nSomethin' must be wrong to drive 'em to it. I can't ask 'em what happened--yet--but maybe ye can find some clues in their village?", completion = "So, what did ya find?", objectives = "Uncover 6 clues in Winterpelt Hollow.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66554] = { id = 66554, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aggressive Self-Defense", description = "With the Winterpelt all in a tizzy, I don't imagine they'll appreciate ya poking around up there. \n\nDon't be afraid to defend yourself if they start somethin'. A firm reminder that ya mean business might knock some sense back into 'em.\n\nTry not to kill anyone though, will ya? I know how ya adventurin' types can get.", completion = "Hopefully ye didn't go too hard on 'em.", objectives = "Defeat 6 Winterpelt furbolgs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66555] = { id = 66555, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bear With Me", description = "Aye, sounds like a right mess up there--like a storm blew through and wrecked the whole place. I can see why they'd be up in arms, but why attack us?\n\nThis would be a lot easier if we could just talk it out, but the Winterpelt are famously tight-lipped and don't seem to speak any of the common branches of Furbolg-ish. Furbolgian? Eh, ye know what I mean.\n\nI don't suppose ya happened to have a nice chat with any of 'em while ye were checking in on them, did ye?", progress = "Are ye even listenin'?", completion = "Now to translate this mess...", objectives = "Assist Sonova's translation.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66556] = { id = 66556, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ice Cave Ya Got There", description = "Well, yer accent is atrocious, and ten-thousand years o' isolation an' linguistic drift hasn't done us any favors, but I think I got a rough impression at least.\n\nThe common thread in what they were tryin' to say was somethin' aboot a \"bad cave wind\" or an \"evil storm cave.\" That, or their laundry was too Thursday?\n\nLook, this isn't like learnin' Gnomish; there're goin' to be some hiccups. I'm pretty sure aboot the cave though, so let's start there.", progress = "That's the best I got. Ye try translatin' this stuff if ye don't like it.", completion = "I told ye I had the cave part right. Now we can see about establishin' some proper diplomatic relations.", objectives = "Investigate the cave.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66557] = { id = 66557, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Academic Acquaintances", description = "Aye, this Winterpelt variation on furbolg is provin' to be a tough nut to crack even for me.\n\nI've got some colleagues down in Camp Nowhere who might be able to help. I hear there are other furbolg tribes in the area, and comparin' notes on those dialects might give us somethin' to go off of.", completion = "I speak my own tongue, yes, but there is something I need your help with first.", objectives = "Find another expert in furbolg languages in Camp Nowhere.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66558] = { id = 66558, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rowie", description = "You were the one that came back with the others from Brackenhide, weren't you? Then you probably know what happened to Kaqiata...\n\nHer son, Rowie, has been distraught ever since Brena and the others returned without her. I'll stay here in case he comes back, but could you look for him? \n\nI think he ran off towards the ice cave to the east. He said something about trying to fight the yeti in there!", progress = "I have to prove myself!", completion = "Thanks for helping me. You're nice.", objectives = "Find Rowie.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66559] = { id = 66559, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Back To Camp", description = "I saw Mordigan run out of there like a dwarf possessed. I'll go chase him down and make sure he gets back to the others in one piece.\n\nIf you hug the cliff and jump down the waterfalls, you should be able to avoid stirring up any more of the gorlocs. \n\nSee you back at camp.", completion = "It appears you've managed to return our dwarf. And in a single piece, no less. On behalf of both our team and the Dragonscale Expedition, I thank you. \n\nWe'll get Mordigan some fluids, then start packing up. \n\nThere's nothing in these hills save blood and salt.", objectives = "Return to Examiner Rowe in Whaler's Nook.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66575] = { id = 66575, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Item as Questgiver: Vial", description = "<This strange vial nestled amongst the odds and ends of the Tarasek stash seems to be filled with a viscous, bubbling fluid.>\n\n< It would be wise to show this to Alvi.>", sourceObjective = "Turn in the item to Waywatcher Alvi.", sourceObjectiveStatus = "unverified-source-field" }
quests[66577] = { id = 66577, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aspectral Invitation", completion = "I cannot wait to see the Dragon Isles with you, {name}!\n\nNow then, I believe that diminutive ally of yours said something about putting together an expedition.", objectives = "Speak with Wrathion to learn of the Council's meeting.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66578] = { id = 66578, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A > B Reward Test (Low Health)" }
quests[66579] = { id = 66579, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sounds of Healing", description = "<You hear a soothing sound emanating from the disc as it hums softly.\n\nOlea Manu might know more about this.>", completion = "The Jailer is no more. What you bring is proof--Zereth Mortis is beginning to heal itself! You may find new tools born of that healing. Tools that resonate strongly with the Cyphers. With them, you can rid us of the remaining Mawsworn.", objectives = "Bring the Resonating Disc to Olea Manu at Faith's Repose.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66582] = { id = 66582, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Power Procurement", description = "In normal circumstances, the capture of energy is not problematic. However, the energy we require is massive and unstable. This enchanted vessel should provide a safe means of transport.\n\nThere is a region to the southwest filled with energy-laden creatures. The anomalous energy within these creatures is powerful, but unstable.\n\nCapture their energy and return it to me. Then we may embark on the remainder of this journey together.", progress = "Have you collected what we discussed?", completion = "Oh my. The warmth within the vessel is fascinating.", objectives = "Gather energy within the vessel for Warpcaster Delandra at Camp Antonidas.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66584] = { id = 66584, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Additional Waygate Energy", objectives = "You will learn:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66586] = { id = 66586, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Legacy of Tyr: Secrets of the Past", description = "To stop Raszageth from freeing the other Incarnates, the Aspects' power must be restored.\n\nBut this will not be an easy task. The Titans are silent and Keeper Tyr is long dead.\n\nQueen Alexstrasza has devised a plan. In the Badlands lies a Titan facility called Uldaman. She believes Tyr's companions hid a disc of his memories inside its depths.\n \nTake your allies to Uldaman and find the disc for the Dragon Queen. Let us hope Tyr's knowledge can be used to re-empower the Aspects.", progress = "Has the exploration been a success?", completion = "Infinite dragons? Their kind always has been troublesome.\n\nI will inform the Dragon Queen that she must find another way to restore the power of the Aspects.", objectives = "Enter Uldaman in Badlands. Discover the cause of the disturbances.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66588] = { id = 66588, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Swog the Elder", objectives = "Defeat Swog in a Pet Battle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66589] = { id = 66589, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Expeditionary Coordination", description = "The name's Toddy. I'll be headin' up our band of cheery adventurers under the banner of the Dragonscale Expedition. We'll get into the details later. For now, let's focus on gatherin' up our crew.\n\nEvery expedition worth its salt has a variety of folk. We'll be needin' scholars, artisans, and of course explorers.\n\nWell? What're you standin' here for? Assemble that crew!", progress = "Everyone packed and ready?", completion = "That was fast!\n\nEager to get to the Dragon Isles, eh? Me too!", objectives = "Recruit explorers, artisans, and scholars throughout Stormwind for the expedition to the Dragon Isles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66595] = { id = 66595, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dormant Discovery", description = "<Nevermind how this curious parchment ended up in your bags. What's important are the contents of the message.>\n\nMembers of the Dragonscale Expedition:\n\nYour assistance is required! Report to the Rubyscale Outpost at once!\n\n<Before the signature can be read, the magical lettering inscribed on the note dissipates into a cloud of white and blue-tinted dust, leaving behind an empty page and a deliciously flowery scent in the air.>", completion = "Message? What message?\n\nWhat do ye mean it vanished mysteriously?\n\nWell, no matter. We've got much to discuss.", objectives = "Deliver the message to Thaelin Darkanvil at the Rubyscale Outpost in The Waking Shores.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66596] = { id = 66596, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Whispers on the Winds", progress = "Our journey begins with you.", completion = "Your reaction is understandable. I dare say I felt the same.", objectives = "Speak with Archmage Khadgar in Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66597] = { id = 66597, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "This Old Stone", description = "This stone behind me is just one piece of, what do ye call it--ancient technology--we stumbled upon here in the Isles.\n\nBut, we're not entirely sure what they are just yet. Baffling, really.\n\nWe've sent word to some friends to see if they can help. In the meantime, perhaps ye can figure out how tae use it?", progress = "So. Is there more to it, or is it really just a heaping hunk o' stone?", completion = "A what symbol!? That can't be right...\n\n<Thaelin scratches his beard.>\n\nThere's only one way to find out.", objectives = "Inspect the Etched Ancient Monolith.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66598] = { id = 66598, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nightborne Know-How", description = "Ancient symbols aren't really me thing. However...\n\n<Thaelin searches through his belongings, eventually pulling out a map. At the top of the parchment appears the name Antonidas, scribbled in large, sloppy letters.>\n\nAh hah! Here it is!\n\nBit of a trek, but a few of those old magic users can be found... here. \n\n<Pointing to a spot on the map.>\n\nMaybe they have somethin' tae offer.", completion = "Well traveled, I see. These symbols you speak of are quite mysterious, as well as old.\n\nSince you seem interested enough to travel all the way out here to find me, the least I can do is offer some guidance.", objectives = "Locate Warpcaster Delandra at Camp Antonidas in The Azure Span.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66611] = { id = 66611, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clearing the Skies", description = "Can you hear that? Bugs! All around. Some of them are getting pretty big.\n\nWhy don't you and your gliding friend use the thermal behind me and do something about it?", objectives = "Kill 50 insects.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66612] = { id = 66612, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crabtender's Quandry", description = "The crabs are in danger!\n\nThis particular bunch has been through a rough season. Their previous habitat was ransacked by the Primalists, and then I led them to this area only for gorlocs to invade!\n\nI thought they would be safe here, but the gorlocs only nurture aggression in their crabs, leading them to an early demise!\n\nPlease, defeat some of the gorlocs so the crabs can escape!", progress = "These crabs deserve better than to serve a gorloc!", completion = "Aspect's grace shine down on you, {name}! You saved my precious crabs! I will watch them more closely this time. No gorloc will overtake my charges again!", objectives = "Kill 12 gorlocs in Cliffdrip Camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66614] = { id = 66614, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Valinor, the Light of Eons" }
quests[66615] = { id = 66615, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nurgash Muckformed" }
quests[66616] = { id = 66616, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oranomonos the Everbranching" }
quests[66617] = { id = 66617, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mortanis" }
quests[66618] = { id = 66618, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mor'geth" }
quests[66619] = { id = 66619, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Antros" }
quests[66620] = { id = 66620, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Emerald Summons", description = "Merithra, the current leader of the green dragons, wishes for you to meet her in the Emerald Gardens.\n\nDrakonid emissaries from the azure flight have come to learn about the gardens. Things have not always been peaceful with the blue dragons, so it is important to her that relations are kept cordial and positive.\n\nShe is on her perch above the Shady Sanctuary in the Emerald Gardens, at Merithra's Watch.", completion = "Thank you for coming, {name}. My guests are eager to see the Emerald Gardens, and I am pleased to host them.\n\nShall we get started?", objectives = "Speak to Merithra at Merithra's Watch in the Ohn'ahran Plains.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66622] = { id = 66622, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wayward Tools", description = "This is terrible! My *hic* tools seem to have run off when I wasn't looking. I can't *hic* stand the thought of them all alone out there, no doubt scared out of their minds!\n\nWould you round them up for me? Just be patient and *hic* try to soothe their nerves and I'm sure they'll warm right up to you!", progress = "Did you *hic* find them?", completion = "Thank you, {name}! I'll *hic* always remember your heroism!", objectives = "Rescue 6 Wayward Tools.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66633] = { id = 66633, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Make a Statement", description = "These djaradin believe the black dragonflight is finished. They don't fear or respect Wrathion's authority here.\n\nWe need a statement to remind them that the obsidian flight has returned, and that we are stronger than ever.\n\nSlay the djaradin and mark each corpse so they don't forget who rules here.", completion = "Masterfully done, {name}. That's how you send a message.", objectives = "Plant a black dragon banner into the corpses of 12 djaradin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66635] = { id = 66635, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reunited, Once Again", description = "That should be enough. I can sense the others just on the outside of the grove, ready to enter the Dream.\n\nWhen you're ready, speak to me and I will break the ice walls and bring down the dome. I hope that my changes will not dishearten the flight. \n\nWe will not be done, but we will be all together again.", completion = "I cannot believe it. All that I could have hoped for... \n\nShe is here.\n\nBut I can tell that she's changed. I do not know what this means, and I fear we do not have much time to ponder it. We must go after Rymek.", objectives = "Speak with Ysera to lower the barrier.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66636] = { id = 66636, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Other Side", description = "We've finally figured out the placement of the third stone--and ye get to do the honors! I've affixed the stone to what's left of the watcher's staff. Just climb the scaffolding there, hold it up, and watch the show!", progress = "When I get back tae Stormwind, my name is going into the book beside the greatest explorers of our time. \n\nMove over Brann, Toddy's here to stay!", completion = "There's so much to see, and we're just getting started!", objectives = "Open the door with the watcher staff.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66646] = { id = 66646, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Quelling Causalities", description = "The Infinite has forced the energies of time to aggression. This is not good.\n\nPlease slay any time elementals you encounter while assisting Ambassador Chronormu. I will remain here and help her hold Eternus in place.", progress = "Did any of them escape to the past? I wonder if we would realize if they did? Hmmm.", completion = "Excellent work! Usually I am against killing time, but today is an exception.", objectives = "Kill Time Elementals.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66647] = { id = 66647, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elemental Unfocus", description = "Kalecgos and I are under heavy fire in the skies above the mountain. The Primalists are unrelenting and their army endless.\n\nSoon, Kalecgos and I may be overrun by their forces.\n\nBut I have a plan.\n\nAt the base of the mountain is a disturbed orc named Ruvin Stonegrinder. The Kirin Tor fought her numerous times.\n\nShe holds a device that can absorb and redirect elemental energies. \n\nTake it from her, then meet me further in.", progress = "The Elemental Focus should prove useful if you can recover it.", completion = "This is it! Hold onto it... you'll need it for what's next.", objectives = "Recover the Elemental Focus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66648] = { id = 66648, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crossing Fate", description = "<Reality spins around you. Your memories of this place become obscured, and shift intensely with each passing moment. Something has changed.>\n\n<You are certain that for all its similarities, this is not the place you once knew. Not exactly.>\n\n<Regardless, the path ahead beckons. Neither deception nor distortion will delay your destiny.>", objectives = "Defeat 30 different Fated raid bosses.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66649] = { id = 66649, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Turning the Wheel", description = "<Through your many trials you feel the power inside you growing. Whatever the source of these anomalies, they now bring you comfort instead of confusion.>\n\n<Dive once more into uncertainty, strive against the darkness, and grasp Fate with both hands.>", objectives = "Defeat 15 different Fated raid bosses.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66650] = { id = 66650, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fate's Finale", description = "<You are calm. The nature of this experience remains unknown, but it is no longer unfamiliar. Your now possess mastery over these ordeals with clarity as your ultimate reward.>\n\n<With clear mind and steady hand you stride forth one last time. Create your own destiny, and watch it unfold under your very feet.>", objectives = "Defeat 5 different Fated raid bosses.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66651] = { id = 66651, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Up to No-khud", description = "The Nokhud and Ukhel clans have overtaken the Eternal Kurgans. Their purpose can only be malign. Our most esteemed ancestors are buried there.\n\nI sent Initiate Zorig to investigate. He still has not returned.\n\nHe is capable, but lacking in confidence. Please help him put a stop to their foul activities!", completion = "Clan Ukhel dishonors itself with dark magic. Now they have moved into the kurgans with their Nokhud allies. Neither clan should be here! I've been watching from here, where I'm safely out of sight.", objectives = "Meet Initiate Zorig at the Eternal Kurgans.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66652] = { id = 66652, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Return to Mender", description = "I can't see what they're doing from here, but I fear they're desecrating the kurgans.\n\nPlease go to the nearest tomb, and see if you can stop the ritual they're performing. \n\nAnd if you find anything that may tell us their purpose here, please bring it back to me.", progress = "Did you stop the ritual? Any clues as to what it was about?", completion = "This spear... it belonged to my mother, Cathan. She was a great hunter. When she got sick, I... I couldn't save her.\n\nLike all great Maruuk centaur, she was buried with her weapon. But this means the Ukhel are using these weapons to raise spirits and bind them to their service - including my mother!", objectives = "Investigate the Ukhel ritual at the nearby mound.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66654] = { id = 66654, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Desecrator Annihilator", description = "My mother was a hero. She deserves peace and rest, not this... enslavement! None of our heroes do.\n\nThey must pay for this. And our ancestors must rest once more with their weapons, with honor. Take the weapons back from those desecrators!", progress = "Did you get the weapons back from those graverobbers?", completion = "This is a good start. I can use these weapons to free their owners... I hope.", objectives = "Kill Nokhud Desecrators and Ukhel Gravestirrers, and recover the ancestral weapons they have taken.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66655] = { id = 66655, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reagents of De-Necromancy", description = "I fear the spirits will be unable to find their tombs, even if we release them from the Ukhel's grip.\n\nThe Ukhel are also raising the ancestors' animal companions who guided and protected them in life.\n\nBring me the skulls of those animals, and the sacred soil disturbed by these enemies. Combined, these reagents should help the ancestors find peace.", progress = "Do you have the reagents? We must free the ancestors before Clan Ukhel takes them away from the Kurgans.", completion = "Perfect! I should be able to use these to release them from the Ukhel. Then they can return to the rest they deserve.", objectives = "Gather 4 Intact Skulls from risen companions and 6 Clumps of Sacred Soil.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66656] = { id = 66656, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Definitely Eternal Slumber", description = "The ancestors are gripped by this dark magic. They will fight before they follow. The Ukhel raised our fiercest warriors and hunters. Stopping them will be no easy task.\n\nI'm going to come along and help. It's time I put my mother's spear back to use.\n\nOnce they are defeated, use this totem I've crafted to help the subdued spirits find their way back to the kurgans.", progress = "Hurry. We must free these spirits.", completion = "I'm so relieved that my mother is at peace again. Thank you, {name}!", objectives = "Defeat each renowned centaur spirit, then use Zorig's Totem of Respite to release them.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66657] = { id = 66657, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "And Stay Dead!", description = "Tombcaller Arban has holed up in the largest kurgan, where the first Maruuk ancestors were laid to rest. Stop Arban before he raises Maruuk and Teera!", progress = "He'll have no tomb of his own when this is done.", completion = "Unlike my mother, and our ancestors, no one will wish for Arban to live again. Thank you for helping me avenge them.", objectives = "Enter the main kurgan and defeat Tombcaller Arban.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66658] = { id = 66658, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Nokhud Offensive: Founders Keepers", description = "Teera and Maruuk's weapons were removed before we stopped Tombcaller Arban. Our greatest ancestors may fight again in these plains... for the Nokhud.\n\nGo to the Nokhud Offensive. Find Maruuk and Teera. When you have subdued them, bring their weapons back to the Teerakai burial mound. We will lay them back to rest with the honor they deserve, in a place we can protect more easily.", progress = "Were you able to defeat the legendary spirits of our founders?", completion = "I would never have expected such help from an outsider before. You have my thanks.", objectives = "Enter the Nokhud Offensive, defeat Teera and Maruuk, and place their weapons in the Teerakai kurgan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66660] = { id = 66660, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "On Your Mark... Get Set...", description = "<Nozdormu's gaze is unfocused.>\n\nThe further they fall, the faster they travel. They punch holes through the fabric of time which send out great ripples. You will need to be swift to catch them.\n\n<Nozdormu's focus sharpens and shifts to you.>\n\nI will send my timewalkers to help you navigate the timeways and speed your efforts. Avoid entangling with the temporal locals and do not stop until you have found Chronormu!\n\nGo. We have precious little time.", completion = "Are you ready, {name}?", objectives = "Join Andantenormu and Siazerathel in the past.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66661] = { id = 66661, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It's Just a Coin, What Could it Cost?", description = "<This curious object provides more questions than answers. How did you come to have it? What is it used for? Is it dangerous?>\n\n<If the Eternal City does not hold answers for you, then surely the Brokers who trade there will.>", completion = "That coin... no one in Oribos will take its kind, and I doubt you'd survive the trip to the market that could. If I may be so bold, perhaps my associates and I could provide assistance?", objectives = "Seek out a Broker in Oribos for information.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66671] = { id = 66671, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Path to Nowhere", description = "Ye look like a willin' and able adventurer! How would ye like to help out the Dragonscale Expedition?\n\nWe've got ourselves a lovely camp in the middle of a nice bit of wilderness.\n\nThere's plenty for ye to do if ye'd like to take the trip over there. \n\nTalk to me sis, Maddy, when ye get there. She'll get ye all settled in.", completion = "Caddy sent ye? She wasn't here before all the commotion broke out with the tuskarr and the furbolg!\n\nTo say we got things to do in the camp is a wee understatement. We're flooded with problems!", objectives = "Meet Maddy Scattershot at Camp Nowhere within the Azure Span.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66673] = { id = 66673, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Speak to Koranos", description = "The Watchers have observed much over the years. Many of them are lost to the vagaries of time, but we still have Koranos.", progress = "Koranos has been here since the beginning. If he doesn't have answers, he should be able to point you in the right direction.", completion = "The Sundered Flame won't let us recover these stones without a fight.", objectives = "Speak to Koranos in Valdrakken.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66675] = { id = 66675, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aspect Power", description = "The Mother Oathstone is an ancient gift bestowed to our flights by the Titans. If what we have learned is true, I might be able to reactivate it and in doing so restore our aspectral powers.\n\nThough we are unsure of the outcome, if this has the slightest chance of working I must attempt it.\n\n{name}, I would appreciate if you would join me in this.", completion = "What happened, {name}? Where is Alexstrasza?", objectives = "Assist Alexstrasza at the Mother Oathstone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66676] = { id = 66676, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sneaking In", completion = "You've returned! Look--Lizi is going to be all right.", objectives = "Return to Radiya in Ohn'iri Springs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66679] = { id = 66679, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruby Lifeshrine Loop", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66680] = { id = 66680, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Counting Sheep", description = "How frustrating. A rabid stag did this while my brother Olekk and I were scouting.\n\n<Watu gestures at his bloody leg and winces.>\n\nAre you here to help? After the primalists attacked, our herd of argali scattered into the pines. Their wool and milk are essential to the camp's functions.\n\nTake this whistle, which commands Wish to herd the argali back home. Sondo the butcher has her favorite treats if she needs extra encouragement.", progress = "Make haste. Argali are a favorite snack for the local--well, local everything.", completion = "So our argali live. Give Wish an extra pat for me, will you? I would do it myself, but I can't move. <Watu sighs.>", objectives = "Befriend Wish with food, and use Wish's Whistle to save 5 Lost Argali in the Sagecrest Pines.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66681] = { id = 66681, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tempests Abound", description = "If you're venturing out into the pines, please slay any stormtouched animals. This is not easy for me to ask, but they're clearly in pain, unable to be helped, and spreading the aggression.\n\nI suspect it's the primalists' doing. It must be coming from their outpost nearby, where I saw a strange magical altar at work.\n\nI'm going to go investigate again. If I'm not back by the time you return, Scout Watu can brief you on additional tasks. We're grateful for any help.", completion = "The pines should be a little safer now.", objectives = "Kill 8 Stormtouched Beasts in Sagecrest Pines.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66683] = { id = 66683, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Last Resort Analysis", description = "<Watu mumbles to himself, eyes closed and arms crossed.>\n\nOf course I get gored by a stag, of all creatures. Now I'm just another one who needs help. My brother will get all the credit, and no one back home will be surprised.\n\n<Watu looks up.> What? What's that you've got there? Glowing rocks? I'll look at one, but take the rest to somebody else. I'm a hunter, not an archaeologist. <Watu snorts, glaring at his leg.> Maybe this is a sign for me to switch jobs. Go on, you've proven more useful than I.", progress = "<A strange look has overcome Watu. He barely registers your presence, infatuated with turning the shard over in his hands.>\n\nYou see how it glows, like new lightning?", completion = "<Watu stares at shock at his leg, newly bloody and pierced with the shard.>", objectives = "Inquire about the Stormtouched Shards in Pinewood Post.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66684] = { id = 66684, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Storm Chasing", description = "<Watu rips the shard out and gasps for air.>\n\nI...completely lost control. Olekk was right. This terrible magic has to be the primalists' doing. Please, stop them!\n\nI must get my brother back to camp.", progress = "Go with haste! That kind of power must be kept in check.", completion = "You've returned! I felt the destruction of the source from here.", objectives = "Destroy the Primalists' source of storm magic.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66687] = { id = 66687, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Land of the Apex", description = "You should know of Rellen, the Learned, who gave centaur the tools to survive a merciless land. His memory requires offerings from worthy beasts.\n\nTake care, traveler. They are not as dangerous as they were eons past, but they're still the plains' apex predators.", progress = "Have you returned with the offerings?", completion = "You've returned intact. Good. Always respect the animals' prowess.", objectives = "Collect 10 Shadespinner Webs, 2 Slyvern Talons, and 2 Thunderspine Scales.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66688] = { id = 66688, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Signs of the Wind", description = "When the elements, true primals of the world, challenged the centaur, Himia met them with our given gift. The wind.\n\nA singing stone stands strong in the plains. There, you can offer tokens of the wind to evoke her memory. Such tokens may be found all around us--a bird's feather, a plant spore, a river's reeds.", progress = "The singing stone is a morning's ride from here.", completion = "<There are ashen remains of previously offered wind tokens in the iron container.>\n\n<You place what you've gathered on top.>", objectives = "Gather wind tokens and give them to the Offering Vessel near the singing stone.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66689] = { id = 66689, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Than A Rock", description = "<The shards are smooth and slightly hot to the touch. Lightning sparks deep within their core.>\n\n<Maybe Watu or Olekk would know more.>\n\n<The thought of parting with the shard fills you with compulsion to hold the shard close. To keep it forever.>", completion = "<Watu doesn't register your presence. He remains sitting, favoring the injured leg, and has his eyes closed.>", objectives = "Show the Stormtouched Shards to Watu.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66690] = { id = 66690, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Nokhud Offensive: The Final Ancestor", description = "You've proven yourself an ally to us, with genuine interest in our values and way of life. There is one more ancestor I'd like to tell you about, but it will be dangerous.\n\nKill the traitorous Balakar, leader of Nokhud, son of none. He wears a precious medallion at all times. Bring it back to me, and I will be forever in your debt.", progress = "Balakar never parts with the pendant. You'll have to kill him.", completion = "...I thought I'd never see the day.", objectives = "Defeat Balakar Khan and collect the Medallion of the Ancestors in the Nokhud Offensive.\n\nYou can access The Nokhud Offensive solo by queuing for it in Follower Dungeons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66691] = { id = 66691, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waking Shores - Race 01 - Intermediate", description = "This course has a similar layout to the previous, just with more variance in the checkpoint placement.\n\nIf you get stuck, blow the whistle and I'll reset you.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66692] = { id = 66692, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruby Lifeshrine Loop - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66693] = { id = 66693, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tempting Fate: Castle Nathria" }
quests[66694] = { id = 66694, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tempting Fate: Sanctum of Domination" }
quests[66695] = { id = 66695, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tempting Fate: Sepulcher of the First Ones" }
quests[66696] = { id = 66696, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tempting Fate: Fate of the Shadowlands" }
quests[66698] = { id = 66698, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Counting Argali", description = "One of our key resources is our argali herd. Every loss is felt deeply for the strength of our clan.\n\nA few of the argali have gotten separated and have wandered away from the herd. Our shepherds could use your assistance reclaiming them.", progress = "Have you reunited the herd?", completion = "Thank you. Our clan deeply appreciates the assistance.", objectives = "Speak with the Aylaag Shepherd and return the lost sheep to the clan.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66699] = { id = 66699, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ask the Locals", description = "Kalecgos is wise to seek the tuskarr's counsel. They have generations of experience with this land.\n\nMany are resting here on their way to their various camps across the Span. \n\nAsk around! One of them must know about local ley lines.", progress = "I'd offer you a bowl, but you appear to be in a hurry.", completion = "Brena is your best bet.", objectives = "Speak to tuskarr around Camp Antonidas.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66700] = { id = 66700, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Black Locus", description = "It really is quite enticing, isn't it? The Locus was too much for the Sundered Flame. However, it fits just right in my hands. Funny, that.\n\n<Adenedal shakes his head.>\n\nPerhaps not. Not this day. Not again. Take it from me. It is not my burden to bear.\n\nGood bye, dear friend.", progress = "Do you have something to show me?", completion = "This was found at the Nelthazan Ruins? Fascinating. \n\nIts markings are ancient, but they bear a resemblance to other artifacts we have discovered in and around the ancient machinations of Deathwing.\n\nFurther study is necessary.", objectives = "Bring the Black Locus to the Telemancer Aerilyn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66703] = { id = 66703, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Snowball Effect", description = "Snowhide gnolls smart. They know you put food on ice, food is good longer. But just ice no good. Magic ice be better! \n\nThis be the work of shamans. And they put Frostbite here, so he starve to death next to delicious tuskarr meat.\n\nIf {race} want help tuskarrs, time running out. \n\nBut Frostbite knows how to break the spell.\n\nWhy Frostbite help? He no like shamans either.", progress = "Tuskarr friends don't look so good, {race}.", completion = "So the sneaky shamans are dead?", objectives = "Retrieve 3 Snowhide Totems from the Snowhide Shamans in the Azure Span.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66704] = { id = 66704, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mugurlglrlgl!", description = "Mrglgulglrrlglgul! Grurguglullgurl!\n\nGruglrlgllrugl rrgulgrulgrgl grugll gurgull gur. Murgllgllrugl gurgllglrl Murgul gruggullgl. Murguglegurgllgur gurgll gurgulgul guruulgurllgr guuglrllgl.\n\nMgrgulllglll gurl gugll.\n\n<You aren't certain what's being said, but there are lots of stabbing motions. It seems like this murloc wants you to kill something.>", progress = "Murglgulglrrlglgul!", completion = "Lrgktrr O'Glrlrlrl!\n\n<The murlocs appear to be pleased.>" }
quests[66708] = { id = 66708, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Riders in the Snow", description = "Greetings, {class}. This magical dome is truly astonishing, is it not? But even though it protects us from the biting cold and the wilderness, we cannot count on the Kirin Tor forever.\n\nA few days ago, some of our most seasoned hunters ventured into the forests looking for food and supplies, but they never came back. Even though I know their leader, Old Grimtusk, is a seasoned hiker and hunter, it is very hard not to worry about him and his hunting party.\n\nCan you find them for me?", completion = "<This tuskarr lies unconscious on the snow with a wooden spear protruding from his side>", objectives = "Find the missing tuskarr hunters in the Azure Span.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66709] = { id = 66709, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Field Medic 101", description = "<It's hard to say how long this wounded tuskarr has been lying here alone in the forest, but he won't last much longer without help.>", progress = "Of course, take your time. That's what you young pups do best.", completion = "Honestly? I thought your \"help\" would be the end of me.", objectives = "Help Old Grimtusk recover from his wounds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66710] = { id = 66710, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flashfrost Flyover", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66711] = { id = 66711, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Delicacy in the Dark", description = "Due to the nature of our clan, some resources are in short supply. We do not have the luxury of time to claim the land's metal resources.\n\nThe late khan established multiple trade connections with a variety of individuals, and I see no reason to discontinue their services.\n\nThe nearby bay contains buckets where we catch whelks - they're considered a delicacy for some of our neighbors. Bring a collection back to me for use in trade.", progress = "Take care with the traps, they may contain some more aggressive nuisances.", completion = "Ah, this will be helpful.\n\nIt is hard for me to rely on outsiders for such a key resource, but I cannot think of an alternate route.", objectives = "Collect 12 river whelks for Hadari.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66712] = { id = 66712, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flashfrost Flyover - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66715] = { id = 66715, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Extraction", description = "Right now the most important thing is to bring back my people. Preferably in one piece.\n\nAnd as much as it pains me to say this, I'm in no condition to fight them on my own. \n\nWill you help us?", progress = "You look strong, little {race}. Are you?", completion = "You smell like death... Frostbite likes that.", objectives = "Rescue tuskarr from the Snowhide Camp in the Azure Span.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66718] = { id = 66718, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gnolls Must Die" }
quests[66719] = { id = 66719, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One Step Backwards", description = "My friend, it is with great sorrow that I must say that I am familiar with the plight facing your kind in these ruins. If you proceed any further, you too will surely succumb to their madness.\n\nBe it through your nurture or your nature, the call you hear is a physiological one. You have a craving that must be sated.\n\nIt brings me great shame to say that I possess the means to feed this malediction. It will not quite be the same, but you will be able to function... For now.", progress = "I regret that it came to this.", completion = "Perhaps your people and mine are not so different after all.", objectives = "Protect yourself from The Call.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66721] = { id = 66721, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wild Preserve Slalom", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66722] = { id = 66722, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wild Preserve Slalom - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66724] = { id = 66724, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Gleamfisher", description = "I am sorry you have been dragged into this, traveler. \n\nMy brother tends to get... carried away. This is only the latest of his follies. But this one might get him killed. \n\nHe won't listen to me. He probably won't listen to you, either. \n\nOur ancestor, Kauriq the Gleamfisher, though, is the center of his fixation. She may be able to.\n\nPlease catch some Gleamfish and bring them here. I shall use them to help us commune with her spirit, which lingers in this stone.", progress = "Not all my ideas have worked out, but that doesn't mean this one won't!", completion = "Did you hear all that, hero?", objectives = "Retrieve 3 Gleamfish and place them in the offering basket.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66725] = { id = 66725, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wild Preserve Circuit", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66726] = { id = 66726, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wild Preserve Circuit - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
