quests[66729] = { id = 66729, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Conditionals", description = "I don't like the alliance. Remember me? \n\nGo kill Mawsworn.", objectives = "Kill 1 Mawsworn", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66730] = { id = 66730, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "True Survivors", description = "I know we're pretty banged up, but we can't forget why we're here. Our people are counting on us, and I don't plan on letting them down. We've got to find a temporary place for ourselves in these savage parts, and I know just the place.\n\nNow quit whining and MOVE IT.", completion = "That wasn't so hard, was it?", objectives = "Find and speak with Old Grimtusk at the Frozen Lake in the Azure Span.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66732] = { id = 66732, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Apex Canopy River Run", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66733] = { id = 66733, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Apex Canopy River Run - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66734] = { id = 66734, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leave Bee Alone", description = "Oh, thank the Life-Binder! Someone with empty hands!\n\nThese gardens are normally a lovely playground for our whelps, but the bees have multiplied uncontrollably. The blooms returned with vigor--and so have the bees. The whelps are terrified, the dragons are annoyed, and just yesterday one was stung and--\n\n<Vaeros takes a deep breath to center himself then looks at you pleadingly.>\n\nWill you please gather up the bees and relocate them to the lake? Take this smoke diffuser; it will calm them down.", progress = "Try not to be too rough with the bees. They are doing their best. We all are.", completion = "Please tell me the relocation went well.\n\n<Vaeros lets out a deep sigh of relief.>\n\nHopefully the bees will be kept busy pollinating the plants that are far away from our whelps. Thank you, {name}.", objectives = "Use the Smoke Diffuser to calm and gather 8 Bothersome Bees, then release them near the lake.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66735] = { id = 66735, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Just a Trim", description = "The bees scaring the whelps is not the only problem. While pollination is usually a good thing, the recent swarm has caused the flora to grow out of control.\n\nWould you mind taking my gardening shears and cutting back the shrubs? Some have already begun to sprout dangerous lashers, but I hope we can stop more from doing so. An ounce of prevention is worth a pound of cure, after all.\n\nAnd I could... very much use some prevention right now, {name}.", progress = "If you use my gardening shears on anything other than plants, I will be very cross with you.", completion = "Thank you, {name}. With any luck, the bees will have fewer reasons to be close to the whelps now.", objectives = "Prune 5 Overgrown Shrubs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66737] = { id = 66737, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Better Start", description = "Vaeros is diligent, but whelps have a way of finding trouble. Not mine, of course--but I suppose not every dragon rears their clutch to understand the gravity of their station.\n\nWhile I am loathe to encourage outdoor play over study, I will help you safeguard the garden more effectively. Take these seeds and plant them nearby. When mature, the blooms produce a fragrance that insects find disagreeable.\n\nThe gardeners can help you--and maybe my bronze brethren, if you mind your manners.", progress = "Do remember to be courteous to our bronze companions, lest they toss you into a timeline without luxurious stationery and herbal tea.\n\n<Adazius sighs wistfully.>\n\nWhat a terrible existence that would be.", completion = "I am rather surprised you did not earn more than a scathing reproach from Veladormi. She must be feeling generous today.\n\nI suspect the insect problem is now solved. You are welcome.", objectives = "Plant seeds in 6 Fertile Soil patches and allow them to mature.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66777] = { id = 66777, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uktulut Coaster", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66778] = { id = 66778, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uktulut Coaster - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66779] = { id = 66779, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heir Apparent", description = "As Neltharion's heir and leader of the only surviving flight of black dragons, I was not expecting to find myself in competition for my birthright. Particularly not against a self-important whelp younger than you, mortal.\n\nNevertheless, if you need more than these self-evident facts, feel free to speak with members of my flight. There's no need to take my word on the subject.", progress = "My flight awaits.", completion = "I trust that you understand, now.", objectives = "Speak with Sabellian's followers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66780] = { id = 66780, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Claimant to the Throne", description = "I have dedicated myself to saving Azeroth from destruction time and time again, and this fool thinks he can just swoop in and claim the title of aspect? I think not.\n\nTalk to my people, {name}. See what they have to say about me and what I have done for this world.", progress = "Their loyalty is unquestionable.", completion = "Surely you back my claim, do you not, {name}?", objectives = "Speak with Wrathion's followers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66781] = { id = 66781, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Matter of Taste", description = "The disrespect around here!\n\nA couple smelly gorlocs steal bits from our equipment and we have to shut it all doon... Ha! I've been lickin' rocks since before ye were a wee babe! Did nae need nae fancy gnomish gadgetry. \n\nBring me a rock, and I'll prove it!", progress = "Find a good rock yet?", completion = "Perfect! Prepare to witness the most impressive feat o' geology ye've ever seen!", objectives = "Find a rock for Mordigan Ironjaw to lick in Whaler's Nook.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66783] = { id = 66783, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Renewal of Vows", description = "Centuries ago, I made a vow of friendship and cooperation with the first centaur. Although much has changed, I feel it is time for us to renew that vow again.\n\nA recitation was composed to help future generations of centaur remember their bond with the green dragonflight. Each verse must be answered with an offering from the khans. I hope the centaur can still remember the original meanings.\n\nThe choice of gift is critical. Choose the right offering, and our allegiance is bound.", progress = "The recitation is as follows:\n\nFrom the hunters who value skill above all, a rite of passage: a first.\n\nFrom the mystics who commune with the wind, her lightest touch: a lift.\n\nFrom the descendants of the matriarch, a drop of unbroken progeny: a line.", completion = "Now that our bonds are renewed, nothing can stand in our way. By wind and wing, so be it.", objectives = "Help Sansok Khan, Tigari Khan, Khanam Matra Sarest, and Merithra exchange gifts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66784] = { id = 66784, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Starve the Storm", description = "You fight well for one who must balance on only two legs!\n\nIt matters not how hard we fight so long as the Primalists continue to draw reinforcements. We must close that portal, the Storm Corridor!\n\nFight your way into the nearby cavern and slay the Primalist Storm-Summoners holding it open. I will aid you if I am able.", progress = "All this is pointless if that portal remains open!", completion = "Now that we have cut off our enemy's reinforcements, the battle will enter its final stage. Great work, {name}.", objectives = "Kill Primalist Storm-Summoners to close the Storm Corridor Portal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66785] = { id = 66785, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Last Eggtender", description = "I understand your concern, {class}, but all will be rectified shortly as it seems that we are about to have company. \n\nFeel free to stay and witness what transpires. It should be quite cathartic.\n\nDo speak with our egg tender when you have a moment, though. She will no doubt need the support.", completion = "Can you believe it?", objectives = "Speak with Mother Elion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66786] = { id = 66786, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wingrest Roundabout", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66787] = { id = 66787, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wingrest Roundabout - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66788] = { id = 66788, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Egg-cited for the Future", description = "I can scarcely believe it! Eggs of the Black Dragonflight! After all this time!\n\nBut look at the state of this place! It will not do at all! Nothing is too good for these eggs.\n\nThough with those two blowhards squabbling like children for the Life-Binder's favor, you can bet they have not spared a thought for us! You, though, will not leave an old egg tender all alone, will you?", progress = "We are not done yet, young one.", completion = "Thank you, {name}. I feel like we have a future once more.", objectives = "Help Mother Elion restore the area.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66805] = { id = 66805, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keys of Loyalty", objectives = "Collect 1 Greater Obsidian Key.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66814] = { id = 66814, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Judgment of Tyr", description = "Welcome to the Veiled Ossuary. Originally built to house and memorialize the dead. Now the likely location of the stone we've come to call the Judgment of Tyr.\n\nWe haven't received reports of any overt Sundered Flame presence here, but the expedition has learned that they prefer to strike unawares.\n\nBe on your guard, {name}.", progress = "All I ever wanted was to study. Instead, I'm sifting through rubble and getting chased by draconic ghosts.", completion = "Tyr held this at one point. Incredible.", objectives = "Recover the Judgment of Tyr.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66825] = { id = 66825, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Ruby Lifecalling", progress = "Ah, I remember my first calling like it was yesterday...", completion = "A Calling can change throughout a dragonspawn's life, but we each cherish our first greatly. Thank you again for participating in our ceremony.", objectives = "Participate in the Lifecalling Ceremony at the Ruby Lifeshrine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66827] = { id = 66827, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flowers of our Labor", description = "The legend says she only sings it for those who prove their devotion to life.\n\nI've been tending this garden for years... And I think my plants and I are finally ready.\n\nI'll start setting up by the pool here. You can help me with the harvest!\n\nGather seed pods from beneath bushes, dragonflowers from sunny fields, and dragonfruit high in the trees. You can borrow my old rake to help with those. And watch out--sometimes the foliage can be feisty!", progress = "<Akora talks nervously to herself.>\n\nJust remember the mantras...\n\nFruit that is sweet,\nis harbored from heat.\n\nTilling early the soil,\nsaves future toil.\n\nIf a tree should bare fruit,\ndon't forget its roots...", completion = "Well... at least the animals seemed to enjoy my work.\n\n<Akora tries to smile but is unable to hide her disappointment.>\n\nMaybe the legend was never real at all.", objectives = "Collect 5 Ripened Dragonfruit, 5 Fragrant Dragonflowers and 5 Lush Seed Pods from around the garden to offer to the Dragon Spirit.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66828] = { id = 66828, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Huddle at the Hollow", description = "I've never seen Akora this upset. Usually she's as sunny as her flowers, but that legend means a lot to her. She talks about it all the time. Hm...\n\n<Keshki fidgets with their glasses.>\n\nI don't know a lot about plants, and I don't think frogs would cheer up anyone but me...\n\nBut north of here there's a quiet spot where I do my thinking: Hornswog Hollow. Maybe we can find something to cheer her up there? Or, uh, try to formulate a plan to help?", completion = "As much as I want to cheer up Akora, {name}, taking care of these poor frogs is a bigger priority.\n\nFor the red dragonflight, preserving life always comes first!", objectives = "Meet Keshki at Hornswog Hollow.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66830] = { id = 66830, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hornswoggled!", description = "Oh, those hornswogs make me so mad!\n\n<Keshki stomps her foot angrily, knocking her glasses askew>\n\nThey're big, greedy bullies! Just because the place is named after them doesn't mean they get to jump all around and eat everything smaller than them!\n\nHere, use my jar of fireflies--it's a frog-minder's best friend. It'll calm the frogs enough that you can collect them, and we can get them out of harm's way.\n\nAnd if any hornswogs get in your way, don't be afraid to bully them back!", progress = "Frogs are gentle creatures! It's not fair to push them around like this!", completion = "Whew, all the frogs we helped are in the carrier!", objectives = "Use Keshki's Jar of Fireflies to lure 8 Bullied Frogs to safety.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66831] = { id = 66831, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Home Is Where the Frogs Are", description = "All the frogs are rounded up, {name}! I guess we're, uh, taking the frogs to Akora anyway. They'll be safe at the Life Pools until the hornswogs get bored and move on.\n\nUm, well, I guess we didn't find anything to cheer up Akora. I hope she understands...", progress = "Honestly? I'm just glad the frogs are safe.", completion = "I guess the legend was real this whole time.\n\n<Keshki grins, looking bashfully at Akora.>\n\nAnd maybe we're, um, both pretty good at tending life after all.", objectives = "Meet Keshki back at the Life Pools to release the rescued frogs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66833] = { id = 66833, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Marmoni in Distress" }
quests[66834] = { id = 66834, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rellen, the Learned", description = "Bring your offerings to the central den. You may witness the legend of Rellen, the Learned, who gave centaur our livelihood as we know it.", progress = "The offering den is in the center of Teerakai.", completion = "Rellen established the centaur's footing in these plains. We would have never survived without his teachings.", objectives = "Make your offerings in the offering den and witness each of Rellen's teachings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66835] = { id = 66835, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sundapple Copse Circuit", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66836] = { id = 66836, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sundapple Copse Circuit - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66837] = { id = 66837, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nothing for Breakfast", description = "My brother Valdo was supposed to order more supplies. But it's been a week and nothing has come. \n\nI'm not surprised. The lazy oaf probably took a nap instead! Now we're short on food, and I'm too busy to hunt on top of my chores--and Valdo's! \n\nWould you hunt for us? The meat of the vorquin striders and striped bruffalon south of here would keep the kitchen open until I can order supplies.", progress = "Did you get some vorquin meat? Any bruffalon flanks? Great! I was ready to put fillet of boot on the menu...", completion = "Thanks to you--and no thanks to Valdo--I can feed all these hungry travelers!\n\nHmm... are you looking for a job? I've got a recent \"opening\"...\n\nCan't pay you much, but you can have Valdo's spot! No? Ah well, can't blame me for trying.", objectives = "Collect meat from the vorquin striders and striped bruffalon south of Three-Falls Lookout.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66838] = { id = 66838, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It's Cold Up Here", description = "Being a good innkeeper means anticipating guests' needs. Unfortunately, I didn't anticipate how cold the nights would be here. Oops?\n\nMy guests are going to need blankets--and good, thick ones. Maybe bear pelts will do?\n\nThere are some large bears in the forest just east of here. If you bring me some of their pelts, I'll pay you for them! \n\nPlease? Think of the adventurers and their cold, cold feet...", progress = "Huh? Oh! You're back already?\n\nSorry, I got kind of involved in my card game... \n\nDo you have the pelts?", completion = "Oh! These are awesome. So luxurious and soft...\n\nNow, only if Valdo were here to clean them up!", objectives = "Collect thick bear pelts from thickmane bears.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66839] = { id = 66839, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "It's Brew Time!", description = "The gang had some time off and was hankerin' for a pint, so we bellied up to the inn.\n\nBut, ach! I can nae believe it! They didna have any brew! What kind o' inn is that? One ran by the Stonehinges--that's what kind!\n\nSo we're takin' matters into our own hands! The forest to the east has flowers and herbs that we could use to brew some sweet mead. Feel like helpin' me and doin' some flower pickin'? There'd be somethin' in it for ye!", progress = "Ye get a nice mead-brewin' bouquet yet?", completion = "Oh, these are be-u-ti-ful! This one is spicy! And this one reminds me of Earthroot. Oh, I can taste the sweet mead now...\n\nThank ye kindly, friend! Ye saved me and the gang's afternoon!", objectives = "Gather Blood Berries, Bronze Horn Berries, and Dragon Foil Blossoms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66840] = { id = 66840, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Water Safety", description = "My greatest responsibility is to make sure everyone has access to clean drinking water.\n\nWith the gnolls to the east dealing with the decay, I must make sure that the camp is safe.\n\nI don't want to alarm anyone by personally taking samples, but I feel testing is necessary.\n\nBring me samples from the three nearby waterfalls, and I will reward you handsomely.", completion = "A deep wyrm?\n\nSomething must have driven it away from its underground nest. Whatever spooked this apex predator  must be very terrible indeed.\n\nThank you, {name}, I will make sure to remove the carcass it doesn't contaminate the water.", objectives = "Bring three water samples to Manny Read.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66841] = { id = 66841, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Shard of the Past", description = "I've seen ye runnin' in and out of the camp helpin' people. Ye think ye could help ol' Gannar too?\n\nI surveyed the area, and somethin' caught me old eyes. I think 'tis an ancient potsherd or a jar or somethin' just down south of here at the edge of that waterfall.\n\nNow, I am not much of a swimmer, but I'll give ye some coin and you can deliver the findings to Thanessa Silverbloom.", progress = "You must be {name}.\n\nGannar said you were running some sort of an errand for him?", completion = "This is an unbelievable find! I have never seen ancient pottery like this. And these markings... Give me a moment while I inspect them.", objectives = "Recover and bring the artifact to Thanessa Silverbloom.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66843] = { id = 66843, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Out of Lukh", description = "Ach! Have ye seen me assistant, Lukh?\n\nThe kid wanted a moment to look 'round, but he's been gone for an hour! \n\nI told him it ain't safe here and to nae walk far, but the kid has a head as thick as a ram's.\n\nI can nae say I blame him. it's pretty out here, and he has a thing for flowers.\n\nCould ye help me find 'em? They need me and the wagon back at Three-Falls Lookout!", progress = "Well? Where is he? Did ye find 'em yet? \n\nWe have to go! That collapsed cave at Three-Falls Lookout won't clear itself!", completion = "Thank ye for findin' him. Betcha he won't stray far alone anymore.\n\nHere's a little somethin' for ye help.", objectives = "Find Lukh's whereabouts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66844] = { id = 66844, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Great Shokhari", description = "Of all da animals I have seen here, Shokahri, da great sky vixen, be da most proud.\n\nIt be a shame she preyed on a gnoll shaman, cause now she be crazed with decay. When I saw her eating one of her kits, I knew something was not right.\n\nI took da kits away and brought them here, but Shokhari attacked me, swiping me good. I almost didn't make it.\n\nShokhari must be put down. If da decay rots more of her mind, she be coming for us soon.", progress = "Shokhari got a taste for our flesh now. It be a matter of time before she come to Three-Falls Lookout.\n\nYa must end her suffering!", completion = "Oh, it be a sad time for me, but it had to be done. \n\nHere, take one of Shokhari's kits. I can't keep dem all. Carin' for dem be the least we can do. \n\nRaise it well.", objectives = "Kill Sky Vixen Shokhari.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66845] = { id = 66845, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Legendary Foil", description = "Last night, I was lying in my bedroll, tossing and turning, when an unnatural chill filled the inn. \n\nThen, out of nowhere I saw... the ghost of a draconid! It went through my luggage then vanished into thin air! \n\nBut the true horror is that when I woke up... the ghost had taken my most beloved card!\n\nWould you be so kind as to track down the ghost and get my card back? It is my most prized possession.", progress = "Please, you have to find my legendary card! It was a family heirloom given to me as a young cub. It means the world to me!", completion = "The apparition explained itself and asked for forgiveness.\n\nBut then they asked to play a single match with me. \n\nOur game is apparently very different from what they used to play, and they wanted to try it.\n\nThank you for helping both of us. Maybe the match will be fun?", objectives = "Find the draconid ghost and retrieve the legendary card.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66846] = { id = 66846, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Heart of the Deck", description = "The day the Dragon Isles began their slumber was the day of my very last match. Fate was cruel, and I lost my strongest card before I could compete.\n\nGuo-Hee's card, you see, was mine. I do not know how her ancestors came upon it.\n\nAlas, I cannot claim it as my own as it has been in her family for centuries. That was a foolish mistake on my part.\n\nPerhaps you and I could craft a card together? A truly unique card... Yes! Will you help me?\n\nSpeak to me once you are ready.", progress = "The card we create must be powerful as well. I will need your assistance in creating it!", completion = "This is it! I have never seen such a card before! Such power! So many possibilities!\n\nMagnificent!\n\nThank you, {name}. Now I am ready...", objectives = "Help the apparition craft a new card.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66847] = { id = 66847, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vault of the Incarnates: Fury of the Storm-Eater", description = "No! We locked the Incarnates away to save this world and now Raszageth seeks to free them!\n\nShe cannot succeed, {name}. All life on Azeroth is in grave danger if you do not stop her!\n\nI shall return to Nozdormu at the Seat of the Aspects to plan for whatever is to come. \n\nKhadgar and Kalecgos are already inside with a contingent of allies. Join them to put an end to Raszageth.\n\nGood luck, champion.", progress = "Have you stopped Raszageth? We cannot let her plans go unchecked, {name}.", completion = "This is grave news, {name}. Azeroth is in danger once more, but Khadgar is right.\n\nWe can't lose hope.", objectives = "Enter the Vault of the Incarnates and defeat Raszageth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66848] = { id = 66848, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Omens on the Wind", description = "Ohn'ahra does not speak in language as we do. Her voice carries through the very winds. We mystics are trained to feel her presence, follow her call, and interpret her messages.\n\nI have used the materials you gathered to bind totems to this particular call. Aid me in a ritual to center her voice, then I will interpret her song.", progress = "Ohn'ahra's voice is all around us. You just have to listen.", completion = "The storm is an omen of grim portent. Trouble is brewing.", objectives = "Aid Ohn Seshteng in her ritual.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66856] = { id = 66856, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Becca Black and the Seven Gnomes", description = "The djaradin have ransacked the Obsidian Citadel and stolen a number of valuable artifacts.\n\nWrathion has tasked us to recover every item taken from the Citadel. My team has located several in the area, but we could use your help.", progress = "Have you found everything on the list?", completion = "Excellent work, {name}. Once we've located more of the stolen artifacts, we'll be sure to call for your help again.", objectives = "Recover the missing artifacts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66858] = { id = 66858, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tour the Trading Post", description = "<A flyer, carried by the wind, flaps into your hands.>\n\nFancy yourself a collector, trader, or adventurer? \n\nWe've travelled all over Azeroth collecting goods of the finest quality for someone exactly like you!\n\nVisit one of our outposts in Stormwind or Dornogal and browse all the latest goods!\n\n--T&W Trading Post\n\n<You squint to read the fine print.>\n\nBe sure to present this flyer for some extra Trader's Tender!", progress = "Welcome to the Tradin' Post! \n\nWe've got goods from all over Azeroth for ye to collect. Would ye like to take a look?", completion = "Now that ye've visted the shop and taken a look at our wares, here's a few more Trader's Tender for bringin' in that flyer.\n\nIf you want to keep earnin' tender, then check out the Traveler's Log portion of the Adventure Guide to see what activities ye can do. Complete enough activities and we'll reward you with tender and other amazing items.", objectives = "Collect Trader's Tender from the Collector's Cache and tour the Trading Post.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66860] = { id = 66860, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Relic Recovery: Legacy of Tyr", description = "Kemora has been having me search for any reference to Keeper Tyr and Uldaman that exists. My paper cuts have paper cuts with all the books I have had to go through trying to find what she is looking for. \n\nAlmost all mentions are torn away or destroyed. Aside from this one that I... set aside to show her later. Apparently there is something precious in Uldaman that has been hidden away. I would be very interested in having you bring it to me. \n\nSo that I may help Kemora in her research of course.", progress = "Do you have it?", completion = "Splendid!\n\nI have no idea what this is, but I am sure it is powerful. I shall put it somewhere safe... for Kemora to find later. \n\nDo not worry about telling her, she is quite busy at the moment.", objectives = "Obtain the Hourglass of Shifting Sands from Chrono-Lord Deios in Uldaman.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66861] = { id = 66861, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Relic Recovery: Neltharus", description = "You there! The djaradin have been a menace to dragonkind for far, far too long -- and they have only grown more powerful thanks to the secrets they've managed to pilfer from Neltharus. \n\nGo, find what you can and bring it to me. At this rate, I'll take anything that could give m... us an advantage against them.\n\nOh, and take some friends along. I am sure you think you are strong, but the djaradin are stronger. Trust me.", completion = "A bag? You've brought me a bag? \n\nNo, you cannot have it. Who knows what lies inside? I need to see if there is anything of use... to our research, of course.", objectives = "Obtain the Spellbound Musken-Hide Satchel from Warlord Sargha in Neltharus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66862] = { id = 66862, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Relic Recovery: Ruby Life Pools", description = "So, the Primalist continue with their onslaught on the dragons within the sanctity of the Life Pools? Disgusting. Those pools hold the future of dragonkind.\n\nI am sure Alexstrasza would not mind some extra aid in driving those Primalists out. Show them no mercy. \n\nOh yes... and bring back a trophy of your triumph. I despise any who come for the young.", progress = "Have you dealt with the Primalists?", completion = "<Theldren nods coldly at your offering.>\n\nExcellent work, {name}.\n\nAll who enter shall see these fangs upon our shelf and fear the wrath brought upon those who would stand against the dragon flights.", objectives = "Obtain Kyrakka's Fangs from Kyrakka in the Ruby Life Pools.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66863] = { id = 66863, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Relic Recovery: The Nokhud Offensive", description = "Brutish Nokhud forces on the Ohn'ahran Plains endlessly rebel against their rivals. Their leader, Balakar, is a fearsome and relentless opponent who does not easily admit defeat.\n\nOur storytellers in Valdrakken tell tales of thundering hooves and bone-breaking clubs, but that is nothing compared to witnessing centaur battles first-hand. Perhaps you should venture a bit more closely, hmm? You might even bring back a trophy!\n\nMay soaring eagles watch over you, {name}. I await your return.", progress = "Back so soon?", completion = "<Theldren inspects the musken-hide belt thoroughly.>\n\nOh, my. Is that fresh blood? I'll be sure to clean it up.\n\nOn second thought, it does add to the piece. Such authenticity! Don't you agree?", objectives = "Obtain the Bloodstained Musken-Hide Greatbelt from Balakar Khan in The Nokhud Offensive.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66864] = { id = 66864, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Relic Recovery: Brackenhide Hollow", description = "Ah! I have use of you. The gnolls of Brackenhide Hollow are said to be using decay--a powerful tool, in the right hands. Gnolls do not have the right hands.\n\nWe should be doing our due research on this pressing issue. Go to the Hollow and bring back a bit of their magic so I can... so we can see what kind of powers they've harnessed.\n\nAnd do be careful and take some friends with you. The Brackenhide possess the ability to wither your very bones. \n\nThat would be a pity.", completion = "What's that you've found? Give it here!\n\nYes... this will do quite nicely...\n\nFor our research, of course. Now go--and thank you.", objectives = "Obtain the Decatriarch's Fetish from Decatriarch Wratheye in Brackenhide Hollow.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66865] = { id = 66865, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Relic Recovery: The Azure Vault", description = "The Azure Vault is said to hold some of the oldest and most powerful artifacts and relics in existence. Anything with that much power must be tak... preserved. \n\nGo, delve into the Azure Vault and see what you can recover. And bring some friends--the place is probably crawling with all kinds of dangerous magical nonsense.", progress = "You won't find anything of interest here, unless, of course, you're looking to speak with me.", completion = "What did you find? Hand it over!\n\nOh, oh yes... this is most fascinating. I'm sure I... we'll learn much from it.", objectives = "Obtain the Crystalline Focus from Umbrelskul in the Azure Vault.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66866] = { id = 66866, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Relic Recovery: Halls of Infusion", description = "Apparently Keeper Tyr had a giant facility below Tyrhold. Kemora is all aflutter with the 'possibilities' of what could lie within.\n\nWhat I know is that the keeper had all sorts of secrets and inventions. Useful ones. I am sure if you happened to wander in and take a look around you could get me something... intriguing.\n\nOh yes, some Primalists may have made it there before you. Dispose of them before they destroy all the good titan relics.", progress = "Hmm? What is it now?", completion = "How kind of you to go into a secret facility, run by one of the most brilliant Keepers in existence, all to bring me back... this.\n\n<Theldren looks distastefully at the object, then starts to stare deeper.>\n\nNevermind. I mean... I suppose I can make this work. Since you went to all the trouble of getting it for me.\n\n<You see him place the object close by him. His eyes dart to it occasionally while a mysterious smile plays over his lips>", objectives = "Obtain the Core of Aqueous Corruption from Primal Tsunami in the Halls of Infusion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66867] = { id = 66867, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Relic Recovery: Algeth'ar Academy", description = "The hallowed halls of Algeth'ar Academy are legendary to dragonkind. I hear they are even opening up their registrations to more than just dragons as well.\n\nTheir library is spectacular, there are books there that even the archives do not possess. \n\nSay... Since they are looking for new students, why not enroll? And while you are there perhaps obtain a library card and see if you can check out an interesting book for me. \n\nOh... I am sure Kemora will be interested as well.", progress = "Yes, yes. How go your studies?", completion = "This... this is all you could bring back? A cover and nothing more?\n\nPerhaps the pages are hidden by magic. Hmmm...", objectives = "Obtain the Headmaster's Ledger from the Echo of Doragosa in Algeth'ar Academy.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66868] = { id = 66868, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Preserving the Past: Legacy of Tyr", description = "I have been going through the archives trying to seek information about Keeper Tyr and surprisingly every mention of Uldaman had been stripped away aside from a half page that mentioned something about a secret he kept there.\n\nFascinating stuff, no? I'm sure there are other secrets he hid in there as well. Perhaps you and some of your friends could go in and search. I would treasure anything you could bring back for me.", progress = "Find anything of interest?", completion = "Wonderful! Though not specifically something of Tyr's, this will still make a fascinating addition to the Archives.", objectives = "Obtain the Time-Lost Curio from Chrono-Lord Deios in Uldaman.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66870] = { id = 66870, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Preserving the Past: Ruby Life Pools", progress = "Yes? Have you brought me something?", completion = "I cannot thank you enough. I will begin research immediately, if there is a change to undo what the Primalists have done I must seek it out.", objectives = "Obtain the Primal-infused Dragon Egg from Kyrakka in the Ruby Life Pools.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66871] = { id = 66871, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Preserving the Past: The Nokhud Offensive", description = "Wars rage to the west. Plains soaked in blood. Battles and lives enduring the pains of an endless confrontation. This is our legacy, {name}.\n\nBeyond that legacy lies our future. For that future, we must preserve what remains of our histories and culture before it is nothing but a memory.\n\nHead west. Seek out the armies of the Khanam Matra and work with our allies to end the suffering of the Maruuk.\n\nTravel well, {name}. May Ohn'ahra guide your way.", progress = "We must do what we can before it is too late.", completion = "This... Where did you get this, {name}?\n\n\n\nWe'll be sure this is given the attention it deserves.", objectives = "Obtain the Plume of the Sky Mother from Balakar Khan in The Nokhud Offensive.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66873] = { id = 66873, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Preserving the Past: The Azure Vault", description = "The Azure Vault was the repository for an astonishing amount of ancient relics and research. What wonders the blue dragonflight must have discovered! \n\nPlease, venture into the Azure Vault and see what you can recover. I am certain there is much to learn! But do be careful--this was the repository for things too dangerous to be left alone in the world.", progress = "What ancient mysteries shall we unravel today?", completion = "This is... poor Sindragosa. To have to witness the pain of a child... I cannot imagine what she must have gone through. \n\nHeartbreaking, but there is a lesson to be learned from this. Great care must be taken when researching ancient magic. I thank you.", objectives = "Obtain Sindragosa's Records from Umbrelskul in The Azure Vault.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66874] = { id = 66874, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Preserving the Past: Halls of Infusion", description = "Did you know that deep beneath Tyrhold there is a giant facility called... The Halls of Infusion? So mysterious! So intriguing! So full of possibility! \n\nKeeper Tyr held many of his secrets there. I wonder what they are? He truly was the most brilliant of all the Keepers. \n\n<Kemora stares dreamily.>\n\nHowever, the Primalists are making a mess of things. They will surely damage all the wonders of Keeper Tyr if they are not stopped. Please, get rid of them before they cause too much harm.", progress = "Have you brought me a secret? Oh! I am ever so excited.", completion = "Oh. So that was the secret Keeper Tyr was hiding.\n\nWell I am sure he had excellent reasons for what he did. He always was thinking ahead. And at least the Primalists did not destroy everything.\n\nPerhaps if I find the key this object will reveal a... nicer secret. \n\n<She looks at you with hopeful, dreamy eyes.>", objectives = "Obtain the Holographic Distributor from Primal Tsunami in the Halls of Infusion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66875] = { id = 66875, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Preserving the Past: Algeth'ar Academy", description = "How wonderful! Algeth'ar Academy is open once again. Headteacher Doragosa must be pleased to be back in her halls of learning.\n\nIt has been quite awhile since I have had a chance to speak with my dear old friend. Perhaps you could you go and see if she is available for tea. It would also give you a chance to enroll in the Academy, I hear it is open to all students now.\n\nI thought that may be of interest to you with how much you visit me and these archives.", progress = "Go! See the Academy and all the wonders it holds.", completion = "Oh Doragosa! I remember this... we shall have to talk it over at tea time.\n\nThank you, {name}. I take it your enrollment went well smoothly?", objectives = "Obtain the Dreamwisp of Entangled Memories from the Headteacher in Algeth'ar Academy.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66877] = { id = 66877, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fen Flythrough", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66878] = { id = 66878, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fen Flythrough - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66879] = { id = 66879, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hornstrider Havoc", description = "Hornstriders! They've got bone-breaking beaks, fast legs for getting away from danger, and they can eat anything in the Isles.\n\nThis Calling's the easiest around! It's just me and my favorite big birds spending time together. And if anything comes up, I know how to wrangle all of the Isles' critters.\n\nWould you mind following me to the hornstrider plateaus up north? I wouldn't mind an extra pair of hands while getting set up.", completion = "I've read so many books on hornstriders, and I've wrestled the biggest baby thunder lizard you ever did see... but I don't know one thing about water elementals!", objectives = "Meet Dazakros in the Overflowing Rapids.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66880] = { id = 66880, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ravine River Run", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66881] = { id = 66881, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ravine River Run - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66882] = { id = 66882, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lost Battlepack", description = "<Talonstalker Kavia might want this.>", completion = "It's still intact. Hopefully it brings the next owner more luck.", objectives = "Deliver the item to Talonstalker Kavia.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66883] = { id = 66883, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ancient Horn Ring", description = "<Exadria might want this.>", completion = "An ancient horn ring? It should be worn to honor those that fell in battles before us.", objectives = "Deliver the item to Exadria.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66884] = { id = 66884, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fireproof Gear", description = "The armor of the djaradin can withstand even the fiercest flames. Such qualities would be of great use in combating them!\n\nSee what you can gather from the djaradin. We can study it, and apply the same enchantments to our own armor.", progress = "Were you able to gather any armor?", completion = "These are perfect samples for studying! We should be able to shore up our own armor quite nicely. \n\nYou have our thanks for your aid, friend.", objectives = "Gather 10 Fireproof Gear from the djaradin of the Dragon Isles for Temnaayu of the Iskaara Tuskarr.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66885] = { id = 66885, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Emerald Gardens Ascent", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66886] = { id = 66886, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Emerald Gardens Ascent - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66890] = { id = 66890, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stolen Tools", description = "We have been plagued by gnolls raiding our supply caravans. They appear to be obsessed with the various engineering tools within. We cannot risk these violent raiders figuring out our specialized art! Also, these thefts have set our production schedule back more than I'd like to admit.\n\nIf you can retrieve some of the stolen engineering parts, we can get back on schedule.", progress = "Have you retrieved the stolen tools?", completion = "These parts will help us get back on track with our engineering projects.", objectives = "Gather 20 Stolen Tools from the gnolls of the Dragon Isles for Dothenos of the Valdrakken Accord.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66891] = { id = 66891, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Explosive Ash", description = "The molten phoenixes in the Dragon Isles create an unusual ash substance once they die. It could be used to create some material improvements for some complex, life-changing machinery. Though I would probably use it for explosives.", progress = "Have you found enough ash?", completion = "This ash could provide the essential component in a variety of machines that would improve the lives of people across Azeroth. But who am I kidding? We're going to make explosives with it. BOOM!", objectives = "Gather 20 Explosive Ash from the phoenixes of the Dragon Isles for Gnoklin Quirkcoil of the Dragonscale Expedition.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66892] = { id = 66892, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deluge Dilemma", description = "Elementals are killing the hornstriders! I know how to wrangle large critters, but I never thought I'd have to go toe-to-toe with an elemental! These aren't anything like baby thunder lizards...\n\n<Dazakros sighs, distressed.>\n\nPlease knock down a few of them elementals. Hornstriders have a lot more sense than we give them credit for. They'll fight back if they have the means to!", progress = "If fighting elementals is anything like wrangling lizards, just give those soggy good-for-nothing's a solid knock to the nose and they'll fall in line!", completion = "And I thought I'd seen it all. Would you look at how these little ones drop from the spring?\n\nTurns out being a caretaker isn't so easy. Thanks for your help, {name}. I've learned a lot from you!", objectives = "Kill 12 Water Elementals in Overflowing Rapids.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66893] = { id = 66893, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beaky Reclamation", description = "I may not know anything about water elementals, but I do know hornstriders!\n\nI've thrown together a salve that'll keep the 'striders healthy and ready to fight. I've never had a chance to apply it to a real hornstrider, but I've done all the studying I can do.\n\nIt's time to put on a brave face and lather them up!", completion = "It's downright uplifting to see the hornstriders take back their home. You brought that to them, {name}. Thank you for your help.", objectives = "Heal 8 Injured Hornstriders in Overflowing Rapids.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66894] = { id = 66894, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Same as the Old Boss", description = "The Worldbreaker dragonkin are a trusting lot. We have followed many different leaders over the years, believing that each will lead us to the Hour of Twilight and the return of Deathwing.\n\nHowever, Deathwing has not returned, and still there is no Twilight.\n\nIt is time for a new leader. You can help bring about the change.", progress = "Are we ready for a new leader?", completion = "You have done well. Now there is ample room for a new leader to rise and bring the Worldbreakers to a better future.", objectives = "Eliminate Aizir the Inflamed.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66895] = { id = 66895, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Same as the Old Boss", description = "The Worldbreaker dragonkin are a trusting lot. We have followed many different leaders over the years, believing that each will lead us to the Hour of Twilight and the return of Deathwing.\n\nHowever, Deathwing has not returned, and still there is no Twilight.\n\nIt is time for a new leader. You can help bring about the change.", progress = "Are we ready for a new leader?", completion = "You have done well. Now there is ample room for a new leader to rise and bring the Worldbreakers to a better future.", objectives = "Eliminate Vyzos the Prophet.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66896] = { id = 66896, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Net Income", objectives = "Collect 10 Warmwater Riverfish and 6 Succulent Snapper Meat.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66897] = { id = 66897, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fuel for the Forge", description = "To make the best blades, you need the heat that only a Magma Core can provide. We try to keep a few on hand as a fuel source for our forges. Lately, we've been running low on cores and could use a resupply.\n\nMagma Cores are obtainable from most lava creatures in the Dragon Isles.", progress = "Have you gathered the Magma Cores?", completion = "The blacksmiths will be glad to have this resupply for their forges.", objectives = "Gather 10 Magma Cores from the lava creatures of the Dragon Isles for Dhurrel of the Maruuk Centaurs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66899] = { id = 66899, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fuzzy Legs", description = "We have received a request for \"Fuzzy Legs\" for tailoring...\n\nDon't look at me, I don't make the requests, I just pass them on. I imagine the legs of tarantulas would fulfill this request.", progress = "Have you gathered the Fuzzy Legs?", completion = "I can't imagine what these will be used for, and I don't really want to think about it, but thank you regardless.", objectives = "Gather 20 Fuzzy Legs from the tarantulas of the Dragon Isles for Gnoklin Quirkcoil of the Dragonscale Expedition.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66900] = { id = 66900, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enchanted Relics", description = "Ah, the tides have brought you at just the right time! Gnolls have stolen some of our relics. These are more precious than most--they have been enchanted. We cannot allow the gnolls to learn our magics!\n\nSomeone of your skill should have no issue identifying the stolen relics. Please, will you lend us your aid?", progress = "Have you retrieved the relics?", completion = "I worry about what the gnolls may have learned about the relics while they had them in their possession.\n\nThank you for retrieving them.", objectives = "Gather 10 Enchanted Relics from the gnolls of the Dragon Isles for Temnaayu of the Iskaara Tuskarr.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66901] = { id = 66901, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Breaking the World" }
quests[66902] = { id = 66902, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bee-Gone" }
quests[66903] = { id = 66903, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clearing the Vault" }
quests[66921] = { id = 66921, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Maruukai Dash", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66929] = { id = 66929, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gotta Collect Them All", progress = "I got a few of the cards out myself, have you gotten the rest yet?", completion = "Thank the aspects! Most of these are still in one piece.\n\nI figured out a way to reverse time on the cards using bronze magic and get them back to mint condition!", objectives = "Get Yumadormu's deck back.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66931] = { id = 66931, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Who Brought the Ruckus?", description = "That was no ordinary quake.", progress = "What could that be?", completion = "I--\n\nAs much as I wish to follow my queen into battle, I must prove worthy of her trust and protect the Lifeshrine.", objectives = "Discover the commotion at the Ruby Lifeshrine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66933] = { id = 66933, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mirror of Sky Dash", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66934] = { id = 66934, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Break the Breaker" }
quests[66935] = { id = 66935, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crystal Quill Pens", description = "There are unique creatures in these lands called crystalspines. They are cute little creatures protected by sharp crystal quills.\n\nWhen I was treating one of our researchers for being stuck by one, I noticed that there was a lingering power resonating within. They might make for an excellent source of enchanting crystals.", progress = "Have you found some crystal quills?", completion = "These are a perfect source of magically resonant crystal.", objectives = "Gather 15 Crystal Quills from the crystalspines of the Dragon Isles for Gnoklin Quirkcoil of the Dragonscale Expedition.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66937] = { id = 66937, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Decaying News", description = "The gnolls and their use of decay magic are concerning. We need to gather as much knowledge as we can, in case the threat escalates. \n\nAs alchemists, we are used to gathering such foul substances safely--plus, we're used to the smell. Will you lend your aid?", progress = "Have you gathered the Rotting Samples?", completion = "We will research these samples and see if we can come up with an alchemical solution to this looming problem.", objectives = "Gather 10 Rotting Samples from the decay gnolls of the Dragon Isles for Dothenos of the Valdrakken.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66938] = { id = 66938, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mammoth Marrow", description = "Creating new and unusual brews is one of our many specialties. While we do enjoy experimenting with new and fascinating ingredients, we have a few common ingredients that we keep in stock. \n\nOne of these ingredients is the marrow from mammoth tusks. We have run short on marrow and would appreciate your help in collecting more for our alchemists.", progress = "Have you gathered enough Tusk Marrow?", completion = "The alchemists of the Maruuk Clan will be pleased.", objectives = "Gather 20 Tusk Marrow from the mammoths of the Dragon Isles for Dhurrel of the Maruuk Centaur.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66939] = { id = 66939, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hunting the Huntmaster", description = "I heard from one of the guards in Camp Nowhere that there's a nasty piece of work mutilating the local wildlife. Calls itself a 'huntmaster'.\n\nHunting is one thing, but I can't abide torturing any living thing. \n\nBesides, my wagon could use a good luck charm.\n\n<Nesingwary spits over the side.> \n\nBring me back its paw.", progress = "How goes the hunt?", completion = "Ah, looks like you were successful. \n\nGood.\n\nHere's hoping the critters around here can rest a bit more easily.", objectives = "Hunt down Huntmaster Krakle around Imbu's Shield.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66940] = { id = 66940, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elixir Experiment", description = "Our alchemists have recently looked into a variety of new ingredients for experimentation. Their most recent interest is... interesting... to say the least.\n\nIt appears that gorloc mucus has some properties that can be beneficial for certain elixirs.", progress = "Have you gathered the mucus from the gorlocs?", completion = "Wonderful. Now we will see what exciting concoctions our alchemists will produce with this.", objectives = "Gather 15 Gorloc Mucus from the gorlocs of the Dragon Isles for Dhurrel of the Maruuk Centaurs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66941] = { id = 66941, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tremendous Tools", description = "The djaradin have some mighty large tools and weaponry. We can easily find a use for such tools, even if only to smelt them down into more tools for ourselves.\n\nBring back some djaradin tools for us to study and use.", progress = "Did you find the djaradin and collect some of their tools?", completion = "The blacksmiths have their work cut out for them. Thank you for collecting these tools.", objectives = "Gather 10 Large Tools from the djaradin of the Dragon Isles for Dhurrel of the Maruuk Centaurs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66942] = { id = 66942, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enemy Engineering", description = "It may be a bit controversial, but I believe that we can study the rituals of the Primalists to learn new ways to channel elemental power. I'm confident that once we understand the pathways of their magic, we can use it to create all sorts of innovative engineering products.", progress = "Did you find some Primal Rituals?", completion = "I've been told that the Primalists reject civilization and seek to bring about its downfall. Ha! The joke is on them. Their rituals will inspire dozens of new gizmos that will bring about the next technological golden age.", objectives = "Gather 10 Primal Rituals from the Primalists of the Dragon Isles for Gnoklin Quirkcoil of the Dragonscale Expedition.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66943] = { id = 66943, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wood for Writing", description = "We've found some unusual information in our studies of the Dragon Isles. For instance, the bark of treants afflicted by decay magic acts similarly to hide parchment. \n\nThis odd parchment is strangely able to hold the magic for more powerful inscriptions. Very useful! Can you help us gather some?", progress = "Were you able to retrieve any bark?", completion = "It's so strange. The bark feels like a fine vellum. Though... holding the untreated sheaf brings dark thoughts into my mind. This amount will suffice for now.", objectives = "Gather 15 Bark Parchment from the decay treants of the Dragon Isles for Dothenos of the Valdrakken Accord.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66944] = { id = 66944, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Peacock Pigments", description = "The peacocks of the Dragon Isles have such colorful feathers! I bet we can make some pigments from them for our scribes to use as ink.", progress = "Have you gathered the Peacock Feathers?", completion = "So colorful! We will make some very nice pigments with these.", objectives = "Gather 8 Peacock Feathers from the peacocks of the Dragon Isles for Gnoklin Quirkcoil of the Dragonscale Expedition.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66945] = { id = 66945, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Icy Ink", description = "The icy beasts in the frozen biomes excrete a very rare and mysterious liquid. The liquid's properties make it the perfect binding agent for our inks. I'm a southpaw so the prospect of not smudging my page is very exciting to me.", progress = "Have you gathered the Icy Excrements?", completion = "Thank you for your hard work. We can make fine ink with these.", objectives = "Gather 20 Icy Excrement from the ice spiders and ice bears of the Dragon Isles for Dothenos of the Valdrakken Accord.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66946] = { id = 66946, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azure Span Sprint", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66947] = { id = 66947, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azure Span Sprint - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66948] = { id = 66948, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Emissary's Arrival", description = "I will admit that I have not left the Emerald Gardens in all my life, and as such, I have never met a centaur, let alone a mortal from the mainland.\n\nHowever, I am not here for a kindly visit, but rather to plead for the centaur's aid in securing our oathstone and protecting our charge.\n\nI am glad to see you are here to help as well. There is much to discuss.", progress = "The Green Dragonflight has lost much over the years. We need the aid of mortals where possible.", completion = "More friendly faces are welcome indeed.", objectives = "Learn about the situation in the Emerald Gardens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66949] = { id = 66949, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trinket Bandits", description = "The gnolls have quite a collection of trinkets. Tuskarr trinkets. They have either stolen them from our villages, or worse, from the brave tuskarr that fell in battle against them. These trinkets are our heritage and should reside with us.\n\nIf you bring some back to me, I will teach you the techniques that are used to make them.", progress = "Have you retrieved the Stolen Trinkets from the gnolls?", completion = "I recognize these trinkets. I remember those they originally belonged to. Thank you for returning them to us.", objectives = "Gather 10 Stolen Trinkets from the gnolls of the Dragon Isles for Temnaayu of the Iskaara Tuskarr.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66950] = { id = 66950, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heart of a Giant", description = "There are various giants within the Dragon Isles that are rumored to contain beautiful gems at their core. We normally don't hunt the creatures of the Isles for treasures, but these giants have caused quite a bit of havoc.\n\nWe may as well collect these gems in the process of clearing out the destructive giants.", progress = "Have you found any gems from within the giants?", completion = "These are indeed beautiful treasures.", objectives = "Gather 5 Giant Cores from the mountain, ice, or molten giants of the Dragon Isles for Temnaayu of the Iskaara Tuskarr.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66951] = { id = 66951, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Population Control", description = "Recently there has been an overpopulation of a few different species on the Dragon Isles. In particular, the rockfang and the bruffalon.\n\nWe don't want to be wasteful, of course. Be sure to collect as much of the hides as you can from the creatures.", progress = "Have you dealt with the overpopulation and brought back some hides?", completion = "Thank you for handling the situation and for not wasting the hides.", objectives = "Gather 25 Salvaged Hides from the rockfang and bruffalon of the Dragon Isles for Temnaayu of the Iskaara Tuskarr.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66952] = { id = 66952, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Gnoll's Clothes", description = "The gnolls are a constant threat, launching bloody raids and attacks against the expeditions and peoples of the Dragon Isles. So how are their clothes so clean?\n\nAfter your battles with these raiders, could you collect a sample of their worn cloth for me to analyze?", progress = "Did you bring the Gnoll-Worn Cloth?", completion = "Thank you for these samples. On casual inspection it seems to just be wildercloth stolen from the tuskarr, but I'll have our tailors really examine the stitching to be sure.", objectives = "Gather 20 Gnoll-Worn Cloth from the gnolls of the Dragon Isles for Dothenos of the Valdrakken Accord.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66953] = { id = 66953, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "All Things Fluffy", description = "The tailors are always anxious to get their hands on that fluffy argali fur. The wool is especially useful for surviving in the freezing cold mountains of the Dragon Isles.", progress = "Did you get some of that Fluffy Fur?", completion = "So fluffy! Yes, this will do.", objectives = "Gather 20 Fluffy Fur from the argali of the Dragon Isles for Dothenos of the Valdrakken.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66956] = { id = 66956, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dragonhunter Igordan" }
quests[66957] = { id = 66957, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Shadow In The Ice", description = "I've heard whispers while passing through Camp Antonidas. Talk of mutilated fauna being found across the icy steppes. Some nothing more than bloody splatters. \n\nWhatever it is, it's got the mages scared and made the local wildlife scarce.\n\nPoke around the top of the glacier. If I was a betting dwarf, I'd say that's where any apex predator worth its salt would stake its claim.\n\nBring me a piece of it so we can soothe the Kirin Tor.", progress = "Be careful. Whatever this thing is, it's strong. And relentless.", completion = "An ice giant? By Magni's bronze beard... And you're in one piece too! Impressive.\n\nI'll show this to the Kirin Tor. Now maybe they'll get off our backs!", objectives = "Investigate the top of the glacier that overlooks Camp Antonidas.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66958] = { id = 66958, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Protect And Herd", description = "I was talking with some hunters out of Iskaara the other day, and they mentioned finding a grisly scene. \n\nApparently, a particularly murderous rhino, Bloodhorn, has been goring the smaller bruffalon in the area. \n\nThe bruffalon have enough competition in Azure Span without worrying about getting their herds thinned out by an invasive brute from out of town!\n\nBring me his horn. I'd like to make a good impression on our Tuskarr friends!", progress = "Remember: watch out for his hooves! That's how rhinos get you.", completion = "Excellent job, {name}! This will go a long way in helping the bruffalon prosper and will hopefully show our Tuskarr neighbors we are also good stewards of this land.\n\nWe could learn a lesson from Bloodhorn. Just cause we're stomping through this beautiful place doesn't give us the right to do what we want with it!\n\nAlways leave the world better than you found it.", objectives = "Hunt down Bloodhorn east of Iskaara.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66959] = { id = 66959, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tour the Trading Post", description = "<A flyer, carried by the wind, flaps into your hands.>\n\nRare antiquities from every corner of Azeroth! Fine goods fit for any taste!\n\nYou will not find these unique treasures anywhere else, friend.\n\nCome see us at one of our outposts in Orgrimmar or Dornogal and gaze in wonder upon the mysteries in store for you!\n\n--Zen'shiri Trading Post\n\n<You squint to read the fine print.>\n\nBe sure to present this flyer for some extra Trader's Tender!", progress = "Welcome to the Trading Post. \n\nWe have goods from all over Azeroth here for your collectin'. Please, take a look.", completion = "Ah, ya brought in one of our flyers! As promised, here's some Trader's Tender ya can use in our shop.\n\nIf ya want to keep earning tender, then check out the Traveler's Log portion of the Adventure Guide to see what activities ya can do. Complete enough activities and we'll reward ya with tender and other amazing items.", objectives = "Collect Trader's Tender from the Collector's Cache and tour the Trading Post.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66960] = { id = 66960, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Klozicc the Ascended" }
quests[66961] = { id = 66961, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Join the Hunt" }
quests[66963] = { id = 66963, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Out For Delivery", description = "I tried to tell Vevesi that I could pull the wagon out of the mud.\n\nBut, no, he insisted on using magic to get it out... And now look what he's done.\n\n<Hauler Bennet sighs.>\n\nWhile I try to talk sense into Vevesi, can you run up the hill to the Basecamp and let Cataloger Wulferd know that he might need to ship another crate of camera supplies over from Boralus?", completion = "<Cataloger Wulferd laughs.>\n\nNot a problem. I packed plenty of spare film in my carry-on.", objectives = "Tell Cataloger Wulferd in the nearby basecamp that his supplies won't be arriving anytime soon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66964] = { id = 66964, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Artifacts in the Wrong Hands", description = "We've got a myriad, no, an incalculable number of problems here!\n\nOh man, where to start! \n\nThe Kirin Tor uncovered a Sundered Flame plot. They're after an artifact called \"Valthrux\".\n\nIt's immensely powerful and... sentient? That's an exponential increase in danger if you're keeping track.\n\nOne Alia Sunsoar went south with a pair of tuskarr to investigate the Sundered Flame. She should have been back by now.\n\nPlease find her and stop the Sundered Flame from acquiring the artifact!", completion = "Finally, a stroke of good luck! We could really use a hand here.", objectives = "Locate Alia Sunsoar in the Lost Ruins within Azure Span.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66968] = { id = 66968, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pruning The Pack", description = "<Nesingwary gestures to the side of the path.>\n\nSee those imprints in the snow? \n\nYeti tracks. \n\nSomething must of riled them up to hunt this close to the road. See if you can't hunt down their pack leader. We don't want them to start ambushing travellers! \n\nIf he's a particularly mean brute, collect his head. That should dissuade the others.", progress = "Careful, friend. Yeti hunt in packs.", completion = "Whoa! Talk about a mean mug... I'm glad you made it back alive! \n\nAs unsavory as making an example of it is, keeping the yeti off the roads is best for them.\n\nAnd us.", objectives = "Hunt down Yetor near Ronin's Shield.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66969] = { id = 66969, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clans of the Plains", description = "While you wait for the emissary to arrive, Sansok Khan is interested to hear how meeting the clans went. She sent me to find you and tell you to meet her in the center of Maruukai to discuss.", progress = "<Sansok Khan smiles at you, welcoming you back.>", completion = "<As Sansok Khan signs, Okir vocalizes for her.>\n\nWhile there are many clans of various sizes throughout the plains, Shikaar, Teerai, Ohn'ir, and Nokhud hold the most power.", objectives = "Report to Sansok Khan in Maruukai.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66970] = { id = 66970, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ty'foon the Ascended" }
quests[66971] = { id = 66971, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Face of Death", description = "Tell me, friend. Have you ever seen the face of death?\n\n<Nesingwary pauses for dramatic effect.>\n\nWhat am I saying? Of course you have.\n\nDeath, after all, has many faces. \n\nI've heard tell from the Imbu tuskarr that one of its faces lives up in these hills. To even say its name is to invite a violent, frigid death:\n\nFrostjaw.\n\n<Nesingwary looks around warily.>\n\nWell, now you have to hunt it--for my sake at least!", progress = "Don't dawdle about. I'm in mortal danger now!", completion = "You're alive!\n\nHa ha! I can't imagine what kind of fight that beastie put up when you cornered him. Azure Span's a little safer thanks to you!\n\nDo me a favor and check on my da...", objectives = "Hunt down Frostjaw north of Winterpelt Hollow.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66989] = { id = 66989, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Helpful Harvest" }
quests[66997] = { id = 66997, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nursery Direction", description = "I'm so grateful that Lasztak has accepted the Calling of a Whelptender! Especially given how many of the precious little things are teething right now.\n\nBeyond that, the nursery gardens are admittedly facing challenges. The whelps are stressed and the tenders are--well, more stressed than usual.\n\nPlease, whenever you have a spare moment, find me in the gardens below. We could use your help as well!", completion = "Thank goodness you're here! You may have noticed the bees on your way in. We must do something about them!", objectives = "Meet Vaeros in the gardens of the Ruby Life Pools.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[66998] = { id = 66998, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fighting Fire with... Water", description = "In all my years of tending to the lava elementals, I have never seen them act like this! We can barely keep them contained to the cave.\n\nDo you have a minute to spare? We'll hold the exit while you thin their numbers inside.\n\nHere, take this bottled water elemental with you.\n\nI always carry a few spare bottled water elementals when I'm looking after the lava elementals. Natural enemies make for good distractions!", completion = "Thank you for a moment's respite. A caretaker's work is never done.", objectives = "Kill lava elementals in the Erupting Cavern.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[67002] = { id = 67002, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azure Span Slalom", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[67003] = { id = 67003, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azure Span Slalom - Advanced", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[67004] = { id = 67004, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Good Things in Large Boxes", description = "Our efforts have created everything we need to open an Earth-Warder's Vault. There are several beneath the Citadel. Locate one and I will reward you.\n\nI have crafted chains to help move it. If you bring the Vault here, we can share in the riches.\n\nWatch for the Vault being moved, as I have dispatched others to find them as well.", progress = "Have you found the Vault?", completion = "Excellent work, {name}. With any luck we can open additional Vaults soon!", objectives = "Locate an Earth-Warder's Vault for me. If you bring it back, we can share in the loot.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[67005] = { id = 67005, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "How to Train a Proto-Drake" }
quests[67006] = { id = 67006, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Quenching the Flame" }
